function gmaps(name,town){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(name+" "+town+(/NY|New York/.test(town)?"":", NY"));}
function isGoogleMaps(u){try{const x=new URL(u);if(x.protocol!=="https:"&&x.protocol!=="http:")return false;const h=x.hostname.replace(/^www\./,"");
  return /^maps\.app\.goo\.gl$/.test(h)||(/^goo\.gl$/.test(h)&&x.pathname.startsWith("/maps"))||/^maps\.google\./.test(h)||(/^google\.[a-z.]+$/.test(h)&&x.pathname.startsWith("/maps"))||(h==="g.co"&&x.pathname.startsWith("/kgs"))||h==="share.google";}catch(e){return false}}
function mapsLink(url,verified,compact){return `<a class="mapslink${compact?" compact":""}" href="${esc(url)}" target="_blank" rel="noopener" title="${verified?"Restaurant's own Google Maps listing":"Search Google Maps"}"><svg viewBox="0 0 24 24" width="13" height="13" aria-hidden="true"><path d="M12 2a7 7 0 0 0-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 0 0-7-7zm0 9.5A2.5 2.5 0 1 1 12 6.5a2.5 2.5 0 0 1 0 5z" fill="currentColor"/></svg>${compact?"Map":verified?"Google Maps listing":"Open in Google Maps"}</a>`;}
