function monthsLabel(m){m=[...m].sort((a,b)=>a-b);const runs=[];let st=m[0],pv=m[0];
  for(let k=1;k<=m.length;k++){if(m[k]===pv+1){pv=m[k];continue;}runs.push(st===pv?MON[st-1]:MON[st-1]+"–"+MON[pv-1]);st=m[k];pv=m[k];}
  if(runs.length>1&&m[0]===1&&m[m.length-1]===12){const a=runs.shift(),b=runs.pop();runs.unshift(b.split("–")[0]+"–"+a.split("–").pop());}
  return runs.join(", ");}
const backIn=id=>{const c=curMonth(),m=SEASON[id].m;for(let k=1;k<=12;k++){const x=(c-1+k)%12+1;if(m.includes(x))return MONL[x-1];}return "";};
