/* ---------- toast + phase-2 stubs ---------- */
function toast(msg){let t=$("#toast");t.textContent=msg;t.hidden=false;clearTimeout(t._h);t._h=setTimeout(()=>t.hidden=true,3800);}
const SOON="Members features switch on in phase 2, when sign-in and the shared database go live.";
document.addEventListener("click",e=>{const s=e.target.closest("[data-soon]");if(s){e.preventDefault();toast(s.dataset.soon||SOON);}});

/* ---------- NY map ---------- */
/* ---------- pan & zoom for every map ---------- */
function panZoom(svg){
  const wrap=document.createElement("div");wrap.className="mapzoom";wrap.appendChild(svg);
  const FULL=[0,0,690,540], start=svg.getAttribute("viewBox").split(/\s+/).map(Number);let vb=start.slice();
  const set=()=>{svg.setAttribute("viewBox",vb.map(n=>n.toFixed(1)).join(" "));};
  const clamp=()=>{vb[2]=Math.min(Math.max(vb[2],60),900);vb[3]=vb[2]*540/690;vb[0]=Math.min(Math.max(vb[0],-150),690+150-vb[2]);vb[1]=Math.min(Math.max(vb[1],-150),540+150-vb[3]);};
  const zoomAt=(f,cx,cy)=>{const nw=vb[2]*f;if(nw<60||nw>900)return;vb[0]=cx-(cx-vb[0])*f;vb[1]=cy-(cy-vb[1])*f;vb[2]=nw;vb[3]=nw*540/690;clamp();set();};
  const toSvg=(clientX,clientY)=>{const r=svg.getBoundingClientRect();return [vb[0]+(clientX-r.left)/r.width*vb[2],vb[1]+(clientY-r.top)/r.height*vb[3]];};
  svg.addEventListener("wheel",e=>{e.preventDefault();const [x,y]=toSvg(e.clientX,e.clientY);zoomAt(e.deltaY>0?1.15:1/1.15,x,y);},{passive:false});
  const pts=new Map();let moved=0,pinch=0;
  svg.addEventListener("pointerdown",e=>{pts.set(e.pointerId,[e.clientX,e.clientY]);moved=0;if(pts.size===2){const [a,b]=[...pts.values()];pinch=Math.hypot(a[0]-b[0],a[1]-b[1]);}});
  svg.addEventListener("pointermove",e=>{if(!pts.has(e.pointerId))return;const prev=pts.get(e.pointerId);const r=svg.getBoundingClientRect();
    if(pts.size===1){const dx=e.clientX-prev[0],dy=e.clientY-prev[1];moved+=Math.abs(dx)+Math.abs(dy);if(moved>4){svg.setPointerCapture&&svg.setPointerCapture(e.pointerId);wrap.classList.add("dragging");}vb[0]-=dx/r.width*vb[2];vb[1]-=dy/r.height*vb[3];clamp();set();}
    pts.set(e.pointerId,[e.clientX,e.clientY]);
    if(pts.size===2){const [a,b]=[...pts.values()];const d=Math.hypot(a[0]-b[0],a[1]-b[1]);if(pinch){const [x,y]=toSvg((a[0]+b[0])/2,(a[1]+b[1])/2);zoomAt(pinch/d,x,y);}pinch=d;moved=99;}});
  const up=e=>{pts.delete(e.pointerId);if(pts.size<2)pinch=0;setTimeout(()=>wrap.classList.remove("dragging"),0);};
  svg.addEventListener("pointerup",up);svg.addEventListener("pointercancel",up);svg.addEventListener("pointerleave",up);
  svg.addEventListener("click",e=>{if(moved>4){e.preventDefault();e.stopPropagation();}},true);
  const ctr=document.createElement("div");ctr.className="mapctl";
  ctr.innerHTML=`<button type="button" data-z="in" aria-label="Zoom in">+</button><button type="button" data-z="out" aria-label="Zoom out">−</button><button type="button" data-z="reset" aria-label="Reset view">⟲</button><button type="button" data-z="full" aria-label="Show all of New York">NY</button>`;
  ctr.addEventListener("click",e=>{const b=e.target.closest("[data-z]");if(!b)return;const cx=vb[0]+vb[2]/2,cy=vb[1]+vb[3]/2;
    if(b.dataset.z==="in")zoomAt(1/1.35,cx,cy);else if(b.dataset.z==="out")zoomAt(1.35,cx,cy);else{vb=(b.dataset.z==="reset"?start:FULL).slice();set();}});
  const hint=document.createElement("span");hint.className="maphint";hint.textContent="Drag to move · scroll or pinch to zoom";
  wrap.append(ctr,hint);wrap.svg=svg;return wrap;
}
/* push pins + red string (the standard marker for trails, crawls and stops) */
const PIN_DEFS='<radialGradient id="pinhead" cx="34%" cy="30%" r="75%"><stop offset="0" stop-color="#FFFFFF"/><stop offset=".3" stop-color="#F3EEE4"/><stop offset=".72" stop-color="#D2C9BA"/><stop offset="1" stop-color="#9F9585"/></radialGradient>';
/* push pin: the needle tip marks the exact spot; the head sits up and to the left, steel shaft angling into the paper */
function pushPin(g,x,y,num,z=1){const r=10/z,hx=x-9/z,hy=y-21/z;
  const sh=el("ellipse",{class:"pinshadow",cx:hx+13/z,cy:hy+14/z,rx:r*.95,ry:r*.72},g);
  const ns=el("line",{class:"needleshadow",x1:x,y1:y,x2:x+9/z,y2:y-5/z},g);ns.style.strokeWidth=2.6/z;
  const nd=el("line",{class:"pinneedle",x1:hx,y1:hy,x2:x,y2:y},g);nd.style.strokeWidth=3.2/z;
  const nh=el("line",{class:"pinneedlehi",x1:hx-.7/z,y1:hy+.4/z,x2:x-.6/z,y2:y-1/z},g);nh.style.strokeWidth=1/z;
  const h=el("circle",{class:"pinhead",cx:hx,cy:hy,r},g);h.style.strokeWidth=(window.DIARY_UI?2.4:.8)/z;
  const hl=el("ellipse",{class:"pinshine",cx:hx-3.2/z,cy:hy-3.6/z,rx:2.6/z,ry:1.8/z},g);hl.setAttribute("transform",`rotate(-35 ${hx-3.2/z} ${hy-3.6/z})`);
  if(num!=null){const t=el("text",{class:"pinnum",x:hx,y:hy+3.6/z},g,num);t.style.fontSize=(10.5/z)+"px";}}
function spreadPins(pts,z=1){const min=22/z,out=[];pts.forEach(p=>{let q=p.slice(),k=0;
  while(out.some(o=>Math.hypot(o[0]-q[0],o[1]-q[1])<min)&&k<12){const ang=-Math.PI/4+k*Math.PI/3;q=[p[0]+min*Math.cos(ang)*(1+Math.floor(k/6)),p[1]+min*Math.sin(ang)*(1+Math.floor(k/6))];k++;}
  out.push(q);});return out;}
function redString(g,xy,z=1,color){if(xy.length<2)return;let d=`M${xy[0][0]},${xy[0][1]}`;
  for(let i=1;i<xy.length;i++){const [a,b]=[xy[i-1],xy[i]];const dist=Math.hypot(b[0]-a[0],b[1]-a[1]);const sag=Math.min(dist*.1,26/z);d+=` Q${(a[0]+b[0])/2},${(a[1]+b[1])/2+sag} ${b[0]},${b[1]}`;}
  const s1=el("path",{class:"stringshadow",d},g);s1.style.strokeWidth=2.6/z;s1.setAttribute("transform",`translate(${2/z},${3/z})`);
  const s2=el("path",{class:"redstring",d},g);s2.style.strokeWidth=2.2/z;if(color)s2.style.stroke=color;}
/* political-map tints: each region gets one of 5 globe colors, never the same as a neighbor (used by the globe palette) */
let _tint=null;function regionTint(){if(_tint)return _tint;_tint={};const pts={};REGIONS.forEach(r=>pts[r.id]=P(r.lat,r.lon));
  const order=REGIONS.slice().sort((a,b)=>REGIONS.filter(x=>Math.hypot(pts[x.id][0]-pts[b.id][0],pts[x.id][1]-pts[b.id][1])<110).length-REGIONS.filter(x=>Math.hypot(pts[x.id][0]-pts[a.id][0],pts[x.id][1]-pts[a.id][1])<110).length);
  order.forEach(r=>{const used=new Set(REGIONS.filter(x=>x.id!==r.id&&_tint[x.id]!=null&&Math.hypot(pts[x.id][0]-pts[r.id][0],pts[x.id][1]-pts[r.id][1])<125).map(x=>_tint[x.id]));
    const cnt=[0,1,2,3,4].map(c=>Object.values(_tint).filter(v=>v===c).length);const free=[0,1,2,3,4].filter(c=>!used.has(c));
    _tint[r.id]=(free.length?free:[0,1,2,3,4]).sort((x,y)=>cnt[x]-cnt[y]||x-y)[0];});return _tint;}
function nyMap({active=[],route=null,routes=null,zoom=null,labels=true,neighbors=true}={}){
  /* CO5A: one map everywhere — New York's 15 regions (county-shaped, colored, dish labels); trail pins and string drawn on top */
  const svg=document.createElementNS(NS,"svg"); svg.setAttribute("class","map ny15"); svg.setAttribute("role","img");
  svg.setAttribute("aria-label","Map of New York's 15 food regions"); svg.setAttribute("viewBox","0 0 690 540");
  svg.innerHTML='<defs>'+PIN_DEFS+'</defs>';
  const z=zoom?690/zoom[2]:1;
  [["Lake Ontario",43.72,-78.2],["Lake Erie",42.47,-79.95],["Atlantic",40.55,-73.2]].forEach(([n,la,lo])=>{const [x,y]=P(la,lo);const t=el("text",{class:"water-lab",x,y},svg,n);t.style.fontSize=(13/z)+"px";});
  const actRg=active.length?[...new Set(active.map(id=>{const rg=regionOfArea(id);return rg&&rg.id;}).filter(Boolean))]:null;
  ny15Base(svg,{labels,z,dimExcept:actRg});
  if(!zoom){const g=el("g",{class:"popsoda"},svg);const a=P(43.28,-76.93),b=P(42.0,-76.93);el("line",{x1:a[0],y1:a[1],x2:b[0],y2:b[1]},g);el("text",{x:b[0]-8,y:b[1]+20,"text-anchor":"end"},g,"← POP");el("text",{x:b[0]+8,y:b[1]+20},g,"SODA →");}
  if(neighbors&&!zoom) NEIGHBORS.forEach(nb=>{const [x,y]=P(nb.lat,nb.lon);const g=el("g",{class:"nbr"},svg);el("text",{x,y,"text-anchor":"middle"},g,nb.place.replace(", Canada",""));el("text",{class:"dish",x,y:y+14,"text-anchor":"middle"},g,nb.dish);});
  if(active.length&&!route&&!routes){const g=el("g",{class:"pinroute areapins"},svg);
    const ps=active.map(R).filter(Boolean).map(r=>({r,p:P(r.lat,r.lon)}));const placed=ps.map(x=>[x.p[0]-19/z,x.p[1]-31/z,x.p[0]+1/z,x.p[1]-11/z]);
    ps.forEach(x=>pushPin(g,x.p[0],x.p[1],null,z));ps.forEach(x=>pinLabel(g,x.p[0],x.p[1],x.r.name,z,placed));}
  if(route){const xy=spreadPins(route.map(s=>P(s.la,s.lo)),z);const g=el("g",{class:"pinroute"},svg);
    redString(g,xy,z);
    xy.forEach((p,i)=>{pushPin(g,p[0],p[1],i+1,z);
      if(z>1.5&&route[i].n){const l=el("text",{class:"stoplab",x:p[0]+14/z,y:p[1]+4/z},g,route[i].n);l.style.fontSize=(11/z)+"px";l.style.strokeWidth=(3/z)+"px";}});}
  if(routes){const g=el("g",{class:"pinroute multi"},svg);const placed=[];
    routes.forEach(r=>{const xy=r.stops.map(s=>P(s.la,s.lo));redString(g,xy,z,r.color);});
    routes.forEach((r,k)=>{spreadPins(r.stops.map(s=>P(s.la,s.lo)).map(p=>{let q=p;let tries=0;while(placed.some(o=>Math.hypot(o[0]-q[0],o[1]-q[1])<12/z)&&tries<6){q=[q[0]+9/z,q[1]-7/z];tries++;}placed.push(q);return q;}),z).forEach(([x,y])=>pushPin(g,x,y,k+1,z));});}
  if(route||routes)svg.classList.add("hasroute");
  if(zoom){svg.setAttribute("viewBox",zoom.map(n=>n.toFixed(1)).join(" "));svg.classList.add(route?"zoomed":"focus");}
  return panZoom(svg);
}
function fitBox(points,minW=110){const xy=points.map(p=>P(p.la,p.lo));const xs=xy.map(p=>p[0]),ys=xy.map(p=>p[1]);
  let x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);let w=Math.max(x1-x0,1)*1.6+50,h=Math.max(y1-y0,1)*1.6+50;
  w=Math.max(w,h*690/540,minW);h=w*540/690; if(w>=440) return null; return [(x0+x1)/2-w/2,(y0+y1)/2-h/2,w,h];}

/* ---------- shared bits ---------- */
const SPONSOR={wing:{name:"WingKingTony",url:"https://wingkingtony.com",line:"The digital home of wing culture: wing crawls, rankings, sauce debates and city wing scenes."}};
function crumbs(list){return `<nav class="crumbs" aria-label="Breadcrumb">${list.map(([t,h],i)=>i<list.length-1?`<a href="${h}">${esc(t)}</a><span aria-hidden="true">›</span>`:`<span aria-current="page">${esc(t)}</span>`).join("")}</nav>`;}
const themeCount=th=>allTrailsCache().filter(x=>x.theme===th).length;
let _atc=null,_atcKey="";const allTrailsCache=()=>{const k=curMonth()+JSON.stringify(SEASON);if(k!==_atcKey){_atc=allTrails();_atcKey=k;}return _atc;};
function trailCard(t){return `<a class="tcard ${t.kind==="Official trail"?"dark":""}" href="${t.href}">
  <span class="crow">${progBadge(t.kind)}${t.fmt&&t.fmt!=="Road trip"?`<span class="fmtag f-${t.fmt.toLowerCase()}">${t.fmt}</span>`:""}<span class="meta">${esc(t.meta)}</span>${seasonBadge(t.id)}</span><b>${esc(t.name)}</b>${themeCount(t.theme)>1?`<span class="themechip">${esc(t.area)} · 1 of ${themeCount(t.theme)} in ${esc(THEMES[t.theme].n)}</span>`:""}${t.by?`<span class="by">by ${esc(t.by)} · example</span>`:""}${t.org?`<span class="by">by ${esc(t.org)}${t.t&&t.t.listed?"":" · sample"}</span>`:""}<p>${esc(t.d)}</p>
  ${t.kind==="Official trail"?(SPONSOR[t.id]?`<span class="presby on">Presented by <b class="paid">${esc(SPONSOR[t.id].name)}</b></span>`:`<span class="presby">Presented by: <i>sponsorship open</i></span>`):""}
  <span class="stops">${t.stops.map(s=>`<span>${esc(s)}</span>`).join("")}</span><span class="score">▲ ${t.score}</span>${typeof DIARY!=="undefined"&&DIARY?`<span class="readbtn">Read the ${esc((t.fmt||"trail").toLowerCase())}</span>`:""}</a>`;}
function themeLink(t){const n=themeCount(t.theme);if(n<2)return "";
  return `<p class="themelink">One of <b>${n}</b> in <a href="#theme-${t.theme}">${esc(THEMES[t.theme].n)}</a>, filed under <b>${esc(t.area)}</b>. <a href="#theme-${t.theme}">Compare them all →</a></p>`;}
PAGES_EXTRA.theme=th=>{const T=THEMES[th];if(!T)return PAGES.notfound();const list=allTrails().filter(t=>t.theme===th);
  const areas=[...new Set(list.map(t=>t.area))].sort((a,b)=>a==="Statewide"?-1:b==="Statewide"?1:a.localeCompare(b));
  const colorOf=t=>STRING_COLORS[list.indexOf(t)%STRING_COLORS.length];
  return {path:`/trails/${th}/`,title:T.n,html:`
  ${crumbs([["Home","#home"],["Trails","#trails"],[T.n,""]])}
  <div class="pagehead"><span class="eyebrow">Theme · ${list.length} crawls, trails & road trips</span><h1>${esc(T.n)} in New York</h1>
    <p class="lede">More than one ${esc(T.one)} trail? Good. They're all here, filed by region so they don't step on each other. Each region's most-voted one is its People's pick.</p></div>
  <div class="split"><div><div class="mapbox" id="mapslot"></div>
      <ol class="maplegend">${list.map((t,k)=>`<li><span class="sw" style="background:${colorOf(t)}"></span><b>${k+1}</b> <a href="${t.href}">${esc(t.name)}</a> <small>${esc(t.area)}</small></li>`).join("")}</ol></div>
    <aside class="tier"><span class="eyebrow">How we keep them straight</span>
      <ul class="why"><li><b>Filed by theme and region.</b> Every trail's address says both: <code>/trails/${th}/hudson-valley/…</code></li><li><b>People's pick per region.</b> The most-voted one in each region gets the top spot; the rest are still one tap away.</li><li><b>No copycats.</b> If a new one shares the same theme, region and most of the same stops as one already here, the builder suggests voting for or remixing that one instead.</li><li><b>One Featured per theme per region</b>, always labeled.</li><li><b>Seasons count.</b> Off-season ones move to the end with "back in [month]."</li></ul></aside></div>
  ${areas.map(a=>{const g=list.filter(t=>t.area===a);return `<section class="band"><div class="sec-head"><h2>${esc(a)}</h2><span class="muted">${g.length} ${g.length===1?"pick":"picks"}</span></div>
    <div class="tgrid">${g.map((t,k)=>(k===0&&g.length>1?`<div class="pickwrap"><span class="peoplespick">People's pick · ${esc(a)}</span>`:"")+trailCard(t)+(k===0&&g.length>1?`</div>`:"")).join("")}</div></section>`;}).join("")}
  <section class="band biz"><div><h2>Know a better ${esc(T.one)} route?</h2><p>Build one for your region. If it's close to one already here, we'll help you make it distinct or remix the original.</p></div><a class="btn" href="#guide">Trail guide</a></section>`,
  after(){$("#mapslot").appendChild(nyMap({routes:list.map(t=>({color:colorOf(t),stops:t.kind==="Road trip"?t.t.stops.map(([rid])=>({la:R(rid).lat,lo:R(rid).lon})):t.t.stops})),labels:true}));}};};
function topList(n=5){return `<ol class="toplist">${allTrails().filter(t=>t.inSeason).slice(0,n).map((t,i)=>`<li><a href="${t.href}"><span class="rk">${i+1}</span><span><b>${esc(t.name)}</b><small>${esc(t.kind)} · ▲ ${t.score}</small></span></a></li>`).join("")}</ol>`;}
const LEVELS=["Local pick","Local favorite","Hometown classic","Institution","Legendary"];
function plateSVG(on){return `<svg class="plate ${on?"on":""}" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10.5"/><circle cx="12" cy="12" r="6"/></svg>`;}
function plates(n,{label=true,sample=false}={}){if(!n) return `<span class="rating none"><span class="pl">${[1,2,3,4,5].map(()=>plateSVG(false)).join("")}</span>${label?`<span class="rname">Not rated yet</span>`:""}</span>`;
  return `<span class="rating" aria-label="${n} of 5 plates: ${LEVELS[n-1]}"><span class="pl">${[1,2,3,4,5].map(i=>plateSVG(i<=n)).join("")}</span>${label?`<span class="rname">${LEVELS[n-1]}${sample?" · sample":""}</span>`:""}</span>`;}
function howtoCard(dishName){return `<div class="listing howto">
  <div class="ph">Your photo</div>
  <div><span class="tag">Example listing</span><b>Your place here</b>${plates(4,{sample:true})}<small>Restaurant, winery, sweet shop or food stop known for ${esc(dishName)}? Travelers are already looking for you. Put your place on the trail.</small></div>
  <ol class="steps"><li><b>Join the site.</b> Free, with Google, Apple, Facebook or email.</li><li><b>Add your place.</b> Name, type, what you're known for, photos and your Google Maps link.</li><li><b>Community check.</b> Members can review your listing, vote on whether it checks out and leave comments.</li></ol>
  <p class="disclaimer">Listings are public. Other members may review your claims, vote on your submission and comment on it. We review flagged listings before changing the map.</p>
  <a class="btn ghost" href="#list">Get on the Trail</a></div>`;}
const SPOTS_IN_TRAILS=()=>{const m={};TRAILS.forEach(t=>t.stops.forEach(s=>{(m[s.n.toLowerCase()]=m[s.n.toLowerCase()]||[]).push(t);}));return m;};
function trailsForRegion(rid){const out=new Set();TRAILS.forEach(t=>{if(t.stops.some(s=>nearestRegion(s.la,s.lo).id===rid))out.add("t:"+t.id);});TOURS.forEach(t=>{if(t.stops.some(([r])=>r===rid))out.add("rt:"+t.id);});MEMBER.forEach(t=>{if(t.stops.some(s=>nearestRegion(s.la,s.lo).id===rid))out.add("t:"+t.id);});
  return allTrails().filter(t=>out.has((t.kind==="Road trip"?"rt:":"t:")+t.id));}

