PAGES.factories=()=>({path:"/features/factory-tours/",title:"Factory Tours",html:`
  ${crumbs([["Home","#home"],["Features","#f-hotdogs"],["Factory tours",""]])}
  <div class="pagehead"><span class="eyebrow">Feature · Made in New York</span><h1>Factory Tours</h1><p class="lede">Watch it get made, then taste it. Chocolate, beer, wine and whiskey makers across New York that open their doors to visitors.</p></div>
  <div class="split"><div class="mapbox" id="mapslot"></div>
    <div class="panel"><a class="feat alt" href="#t-factory" style="margin:0"><span class="eyebrow">Official trail · Saturdays</span><b>The Factory Tour Trail</b><p>Schenectady chocolate, Cooperstown's Belgian-style brewery and a Utica brewery tour, all in one Saturday.</p></a>
      <div class="chips" id="fchips">${["All","Chocolate","Brewery","Winery","Distillery"].map(k=>`<button type="button" class="chip ${k==="All"?"on":""}" data-f="${k}">${k}</button>`).join("")}</div>
      <p class="note" style="margin:0">Hours, prices and booking change. Check each maker's site before you go. Brewery, winery and distillery tastings are 21+.</p></div></div>
  <section class="band"><div class="nlist" id="flist"></div></section>
  <section class="band biz"><div><h2>Run tours of your kitchen, brewery or plant?</h2><p>Factory and maker tours can claim a place on the map and join official trails.</p></div><a class="btn" href="#list">Get on the Trail</a></section>`,
  after(){const mapwrap=nyMap({});const pinsvg=mapwrap.svg;const g=document.createElementNS(NS,"g");pinsvg.appendChild(g);
    spreadPins(FACTORIES.map(f=>P(f.la,f.lo)),1).forEach(([x,y],i)=>pushPin(g,x,y,i+1,1));
    $("#mapslot").appendChild(mapwrap);
    const draw=k=>{$("#flist").innerHTML=FACTORIES.map((f,i)=>[f,i]).filter(([f])=>k==="All"||f.kind===k).map(([f,i])=>`<article class="ncard fcard"><div class="nmeta"><span class="fnum">${i+1}</span><span class="ttype t-local-plates">${esc(f.kind)}</span><span>${esc(f.t)}</span><a href="#r-${f.rid}">${esc(R(f.rid).name)}</a></div>
      <h3>${esc(f.n)}</h3><p>${esc(f.see)}</p><span class="nsrc">${esc(f.note)}</span>
      <span class="stoplinks">${mapsLink(gmaps(f.n,f.t),false)}${f.trail?`<a class="reportbtn" href="#t-${f.trail}">On the Factory Tour Trail</a>`:""}${f.dish?`<a class="reportbtn" href="${dishHref(...f.dish)}">Sponge candy page</a>`:""}</span></article>`).join("");};
    draw("All");$("#fchips").addEventListener("click",e=>{const b=e.target.closest("[data-f]");if(!b)return;document.querySelectorAll("#fchips .chip").forEach(c=>c.classList.toggle("on",c===b));draw(b.dataset.f);});}});
const DOGLINK={"Charcoal Red Hot":["buffalo",3],"White Hot":["rochester",1],"Red Hot":["rochester",1],"Michigan":["plattsburgh",0],"Lil Nippers":["albany",1],"The Coney":["nyc",3]};
PAGES.feature=()=>({path:"/features/hot-dogs-of-new-york/",title:"The Hot Dogs of New York State",html:`
  ${crumbs([["Home","#home"],["Features","#f-hotdogs"],["Hot Dogs of New York",""]])}
  <div class="pagehead"><span class="eyebrow">Feature · Field guide</span><h1>The Hot Dogs of New York State</h1><p class="lede">Same idea, nine different answers. Here's how New York dresses a hot dog, region by region.</p></div>
  <div class="dogs">${DOGS.map(d=>`<article class="dog"><div class="dogpic${d.small?" small":""}">${dogSVG(d.c)}</div><span class="where">${esc(d.w)}</span><h3>${esc(d.n)}</h3>
    <dl><dt>Dog</dt><dd>${esc(d.dog)}</dd><dt>Top</dt><dd>${esc(d.top)}</dd></dl><p>${esc(d.o)}</p>
    ${d.tr?`<span class="try">On the trail: ${esc(d.tr)}</span>`:""}${DOGLINK[d.n]?`<a class="more" href="${dishHref(...DOGLINK[d.n])}">Where to get it →</a>`:""}</article>`).join("")}</div>
  <div class="crow" style="margin-top:18px"><a class="btn" href="#t-hotdog">Follow the Hot Dog Trail</a><a class="btn ghost" href="#pizza-ny">Next: the pizza styles of New York</a></div>`});

PAGES.guide=()=>({path:"/guide/build-a-trail/",title:"Trail guide",html:`
  ${crumbs([["Home","#home"],["Trails","#trails"],["Trail guide",""]])}
  <div class="pagehead"><span class="eyebrow">Trail guide · FAQ</span><h1>How to build a great crawl or trail</h1><p class="lede">A good crawl or trail is one a real person can finish, hungry the whole way.</p></div>
  ${FAQ_HTML}
  <div class="crow" style="margin-top:18px"><button class="btn" type="button" data-soon="The trail builder switches on in phase 2 for members.">Create a trail</button><a class="btn ghost" href="#trails">See example trails</a></div>`});

PAGES.list=()=>({path:"/get-on-the-trail/",title:"Get on the Trail",html:`
  ${crumbs([["Home","#home"],["Get on the Trail",""]])}
  <div class="pagehead"><span class="eyebrow">For restaurants, makers and food stops</span><h1>Get on the Trail</h1><p class="lede">Travelers are already looking for you. Put your place on the trail, right under the regional favorite you're known for.</p></div>
  <section class="band two">
    <div class="tier"><span class="eyebrow">Why get on the trail</span><ul class="why"><li><b>Be found by the right people.</b> Travelers searching for spiedies, sponge candy or lil nippers land on your page.</li><li><b>Become a passport stop.</b> Members come in to stamp your place, and trails send them your way.</li><li><b>Earn your reputation.</b> Members rate you from Local pick to Legendary.</li><li><b>Tell your story.</b> Your history, your dish, your "since 1932."</li></ul></div>
    <div class="tier hi"><span class="eyebrow">The plate rating</span><b>How members rate places on the trail</b>
      <ol class="ratelegend">${LEVELS.map((l,i)=>`<li>${plates(i+1,{label:false})}<span><b>${l}</b> ${["A solid local choice","Locals send their friends here","A regional classic people grew up on","A landmark; the region wouldn't be the same without it","Plan the trip around it"][i]}</span></li>`).join("")}</ol>
      <p style="margin:0" class="muted">Ratings come from member votes and the community check. Places that hold "Legendary" earn a window decal and top spot on the dish page.</p></div>
  </section>
  <section class="band"><div class="sec-head"><h2>Who can get on the trail</h2></div><div class="types">${["Restaurant","Winery","Brewery or distillery","Candy, chocolate or sweets","Bakery","Famous food stop or stand","Farm, dairy or market","Factory or maker tour","Food tour"].map(x=>`<div><b>${x}</b></div>`).join("")}</div></section>
  <section class="band two">
    <div class="tier"><span class="eyebrow">Basic</span><b>Name, town and a link under the dish</b><p>Your Google Maps link, so travelers can get directions in one tap.</p></div>
    <div class="tier hi"><span class="eyebrow"><span class="paid">Featured</span></span><b>Photos, hours and top placement</b><p>Top spot on the dish page, photos, hours and a member perk if you offer one. Pricing set at launch.</p></div>
  </section>
  <section class="band"><div class="sec-head"><h2>How it works</h2></div>
    <ol class="steps big"><li><b>Join the site.</b> Free, with Google, Apple, Facebook or email.</li><li><b>Add your place.</b> Business name, type of place, what you're known for, photos and your Google Maps link.</li><li><b>Community check.</b> Members can review your listing, vote on whether it checks out, rate it in plates and leave comments.</li></ol>
    <p class="disclaimer" style="max-width:70ch">Listings are public. Other members may review your claims, rate and vote on your submission, and comment on it. We review flagged listings before changing the map.</p>
    <div class="crow" style="margin-top:12px"><button class="btn" type="button" data-soon="Getting on the trail opens in phase 2, when sign-in goes live.">Join and get on the trail</button></div></section>
  <section class="band biz"><div><h2>Want to run or sponsor a trail?</h2><p>Organization trails for chambers, BIDs and tourism boards, plus official trail sponsorships.</p></div><a class="btn" href="#programs">Trail programs</a></section>`});

PAGES.programs=()=>({path:"/trail-programs/",title:"Trail programs",html:`
  ${crumbs([["Home","#home"],["Trails","#trails"],["Trail programs",""]])}
  <div class="pagehead"><span class="eyebrow">For members, organizations and sponsors</span><h1>Trail programs</h1><p class="lede">Three ways to put a trail on the map. Members are always free.</p></div>
  <div class="progcols">
    <article class="prog p-mem"><span class="pbadge p-mem">Member · free</span><h2>Member trails</h2><p class="who">For anyone who joins the Local Legends Map.</p><div class="price">Free with membership</div>
      <ul><li>Build and publish your own trails</li><li>Built-in trail check keeps it reasonable</li><li>Share with other seekers, collect votes</li><li>Earn Miles toward Trail Blazer status</li><li>Top-voted trails get featured</li></ul>
      <button class="btn" type="button" data-soon>Join free</button></article>
    <article class="prog p-org"><span class="pbadge p-org">Organization</span><h2>Organization trails</h2><p class="who">For chambers, BIDs, tourism boards, CVBs, festivals, nonprofits and food tour companies.</p>
      <div class="levels">
        <div><b>Community</b><span>Nonprofits and small organizations</span><ul><li>Verified "Local organizer" badge</li><li>Up to 3 trails</li><li>Event dates and a link to your site</li></ul></div>
        <div><b>Regional Partner</b><span>Tourism boards, CVBs and larger organizations</span><ul><li>Everything in Community</li><li>Unlimited trails, your logo on each</li><li>Featured on your region's pages</li><li>Printable passports and QR codes for every stop</li><li>Trail stats: views, follows and stamps</li><li>A seasonal challenge each year</li></ul></div>
      </div>
      <button class="btn" type="button" data-soon="Organization trail applications open in phase 2.">Apply as an organization</button></article>
    <article class="prog p-off"><span class="pbadge p-off">Official</span><h2>Official sponsored trails</h2><p class="who">For brands, businesses and tourism boards that want to present a Local Legends Map trail.</p>
      <div class="levels">
        <div><b>Stop Sponsor</b><span>A business already on an official trail</span><ul><li>Photos and hours on its stop</li><li>A perk for passport holders</li><li>"Stop sponsor" tag</li></ul></div>
        <div><b>Presenting Sponsor</b><span>One per trail</span><ul><li>"Presented by" name and logo on the trail page, cards and passport</li><li>A mention in the news ticker</li></ul></div>
        <div><b>Title Sponsor</b><span>One per trail per season</span><ul><li>Everything in Presenting</li><li>Newsletter and social feature</li><li>A sponsored challenge with a prize</li><li>Co-branded printed passport</li></ul></div>
      </div>
      <button class="btn" type="button" data-soon="Sponsorship inquiries open in phase 2.">Sponsor a trail</button></article>
  </div>
  <section class="band"><div class="sec-head"><h2>Compare</h2></div>
    <div class="cmpwrap"><table class="cmp"><thead><tr><th></th><th>Member</th><th>Organization: Community</th><th>Organization: Regional Partner</th><th>Official sponsor</th></tr></thead><tbody>
      ${[["Cost","Free","Annual fee","Annual fee","Per trail, per season"],["Who builds the trail","You","Your organization","Your organization","Local Legends Map"],["Number of trails","Several","Up to 3","Unlimited","The trail you sponsor"],["Badge","Member","Verified organizer","Verified organizer + logo","Presented by / Title"],["Featured placement","When top-voted","Region list","Region pages","Trail, ticker, newsletter"],["Passports and QR codes","Digital","Digital","Printable + QR","Co-branded print (Title)"],["Stats","Votes","Votes","Views, follows, stamps","Views, follows, stamps"]].map(r=>`<tr><th>${r[0]}</th>${r.slice(1).map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}
    </tbody></table></div>
    <p class="muted" style="margin:0">Pricing will be set at launch.</p></section>
  <section class="band"><div class="sec-head"><h2>How we keep trails honest</h2></div>
    <ul class="rules"><li><b>Money never picks the stops.</b> The Local Legends Map chooses the stops on official trails. Sponsors present a trail; they don't buy their way onto it.</li>
    <li><b>Sponsorship is always labeled.</b> "Presented by," "Title sponsor" and "Stop sponsor" are shown wherever they apply.</li>
    <li><b>Everyone follows the trail guide.</b> Organization and member trails get the same trail check: reasonable stops, reasonable time.</li>
    <li><b>Members vote on everything.</b> Official, organization and member trails all compete in the same Top trails ranking.</li></ul></section>`});
