const townIndex=[]; REGIONS.forEach(r=>r.towns.forEach(t=>townIndex.push([t,r.id])));
function bindSearch(form,input,msg){const f=$(form); if(!f) return; f.addEventListener("submit",e=>{e.preventDefault();
  const raw=$(input).value.trim(), q=raw.toLowerCase().replace(/,?\s*(ny|new york)$/,"").trim(); const m=$(msg);
  if(!q){m.textContent="Type a city or town in New York.";return;}
  {const ch=catSearch(q);if(ch){if(typeof H2P!=="undefined"&&H2P[ch])location.href=H2P[ch];else location.hash=ch;return;}}
  let hit=townIndex.find(([t])=>t.toLowerCase()===q)||townIndex.find(([t])=>t.toLowerCase().startsWith(q))||townIndex.find(([t])=>t.toLowerCase().includes(q));
  if(!hit){REGIONS.forEach((r)=>r.dishes.forEach((d,i)=>{if(!hit&&d.n.toLowerCase().includes(q))hit=["",r.id,i];}));}
  if(!hit){const r=REGIONS.find(r=>r.name.toLowerCase().includes(q)); if(r) hit=["",r.id];}
  if(hit){{const _h=hit[2]!=null?dishHref(hit[1],hit[2]):`#r-${hit[1]}`;if(H2P[_h])location.href=H2P[_h];else location.hash=_h;}} else {logMissing(raw);MISSING_Q=raw;m.textContent="";if(location.hash==="#missing")route();else location.hash="#missing";}});}

