function thankContributor(what,town){if(!EARNED.has("welcome")){EARNED.add("welcome");
    showBadge({k:"welcome",title:"Welcome aboard!",line:`Thanks for contributing${town?` to ${esc(town)}`:""}. You just helped put <b>${esc(what)}</b> in front of everyone headed that way.`,next:"Next badge: <b>Put It on the Map</b>, when your pick is accepted."});}
  else toast(`Thanks! "${what}" is headed to the board. Members vote, then the editor decides.`);}

/* ---------- no results: "Help us put it on the map" ---------- */
let MISSING_Q="";
/* searches that found nothing; in the live site this is a shared table the editor reviews. Seeded samples are labeled. */
const MISSING_LOG=[{q:"Burlington, VT",n:6,sample:true},{q:"Pittsburgh",n:4,sample:true},{q:"half sours",n:3,sample:true}];
function logMissing(q){const k=q.toLowerCase();const e=MISSING_LOG.find(x=>x.q.toLowerCase()===k);if(e)e.n++;else MISSING_LOG.unshift({q,n:1});}
function lev(a,b){const m=[];for(let i=0;i<=a.length;i++){m[i]=[i];}for(let j=1;j<=b.length;j++)m[0][j]=j;
  for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)m[i][j]=Math.min(m[i-1][j]+1,m[i][j-1]+1,m[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return m[a.length][b.length];}
function didYouMean(q){q=q.toLowerCase();const c=[];townIndex.forEach(([t,rid])=>c.push({label:t,sub:R(rid).name,href:`#r-${rid}`,k:t.toLowerCase()}));
  REGIONS.forEach(r=>{c.push({label:r.name,sub:"Region",href:`#r-${r.id}`,k:r.name.toLowerCase()});r.dishes.forEach((d,i)=>c.push({label:d.n,sub:r.name,href:dishHref(r.id,i),k:d.n.toLowerCase()}));});
  return c.map(x=>({...x,d:Math.min(lev(q,x.k),...x.k.split(/\s+/).map(w=>lev(q,w)))})).filter(x=>x.d<=Math.max(2,Math.floor(q.length/4))).sort((a,b)=>a.d-b.d).slice(0,4);}
PAGES_EXTRA.missing=()=>{const q=MISSING_Q;const dym=q?didYouMean(q):[];
  return {path:"/not-on-the-map-yet/",title:"Help us put it on the map",html:`
  <section class="missinghero">
    <span class="eyebrow">Not on the map yet</span>
    <h1>${q?`We haven't mapped "${esc(q)}" yet.`:"We haven't mapped that yet."}</h1>
    <p class="lede">You might know something we don't. Tell us the local legend, where locals get it and how they celebrate it, and we'll put it on the map.</p>
    ${dym.length?`<div class="dym"><span>Did you mean</span>${dym.map(x=>`<a href="${x.href}"><b>${esc(x.label)}</b><small>${esc(x.sub)}</small></a>`).join("")}</div>`:""}
    <form class="missingform" id="missingform" novalidate>
      <label class="f">Town, city or area<input name="town" value="${esc(q)}" placeholder="Cooperstown" required maxlength="80"></label>
      <label class="f">What's the local legend there?<input name="food" placeholder="The dish, drink or treat locals swear by" required maxlength="80"></label>
      <label class="f">Where do locals get it? (optional)<input name="place" placeholder="Restaurant, stand, bakery or farm" maxlength="100"></label>
      <label class="f">Any festival or event that celebrates it? (optional)<input name="fest" placeholder="Name and month, if you know" maxlength="100"></label>
      <p class="ferr" id="missingerr" aria-live="polite"></p>
      <div class="crow"><button class="btn" type="submit">Put it on the map</button><span class="muted">It goes up for a vote; the editor makes the final call.</span></div>
    </form>
    <p class="missingalt">Or keep exploring: <a href="#ny">New York's 23 food regions</a> · <a href="#cravings">every regional delight</a> · <a href="#events">festivals and tastings</a></p>
  </section>`,
  after(){const f=$("#missingform"),err=$("#missingerr");f.addEventListener("input",()=>err.textContent="");
    f.addEventListener("submit",e=>{e.preventDefault();const town=f.town.value.trim(),food=f.food.value.trim();
      if(!town){err.textContent="Tell us the town or area.";f.town.focus();return;}
      if(!food){err.textContent="Tell us the local legendary food there.";f.food.focus();return;}
      const e2=MISSING_LOG.find(x=>x.q.toLowerCase()===town.toLowerCase());if(e2){e2.tip=(e2.tip||[]).concat([{food,place:f.place.value.trim(),fest:f.fest.value.trim()}]);}else MISSING_LOG.unshift({q:town,n:1,tip:[{food,place:f.place.value.trim(),fest:f.fest.value.trim()}]});
      f.reset();thankContributor(food,town);});}};};

// === CO4 === Travel Diary design + growth features (Change Order #4)
const CO4_CONFIG = {
  features: { localQuotes:false, thisWeekend:true, planTrip:true, seasonalPages:true, organizerHub:true, sponsorSlots:true, sponsorPage:true, shareCardFeed:true },
  forms: { submitEvent:"[EVENT SUBMIT FORM URL]", hostCrawl:"[HOST A CRAWL FORM URL]", sponsorInquiry:"[SPONSOR INQUIRY FORM URL]" },
  social: { facebook:"[FACEBOOK PAGE URL]", instagram:"[INSTAGRAM URL]" }
};
const DIARY=!!window.DIARY_UI;
const SITE_URL="https://locallegendsmap.com";
const isPh=v=>!v||/^\[.*\]$/.test(String(v).trim());       /* still a [PLACEHOLDER]? */
/* paid slots. Empty by default; every filled slot is labeled and never ranked.
   presentedBy:{[trailId or seasonId]:{name,url,line}}, eventSpotlight:{eventId,name,url}|null,
   seasonal:{[seasonId]:{name,url,line}}, newsletter:{name,url}|null.  Featured stops stay in the trail-builder logic. */
