if(DIARY){STRING_COLORS.splice(0,STRING_COLORS.length,"#ED7912","#2F6FAE","#107B4C","#C9620A","#7A3E8E","#0B7568");
  BADGES.welcome.fill="#F1C50E";BADGES.welcome.ink="#111111";BADGES.onmap.fill="#107B4C";BADGES.onmap.ink="#FFFFFF";}
const LS={get(k){try{return localStorage.getItem(k);}catch(e){return null;}},set(k,v){try{localStorage.setItem(k,v);}catch(e){}}};
const words=s=>s.trim().split(/\s+/).filter(Boolean).length;
/* 40–60 word answer from data sentences: add sentences until 40+, cut at 60 */
function answerText(sents){let out=[];for(const s of sents.filter(Boolean)){out.push(s.trim());if(words(out.join(" "))>=40)break;}
  let t=out.join(" ");if(words(t)>60){t=t.split(/\s+/).slice(0,58).join(" ").replace(/[,;:]$/,"")+"…";}return t;}
const listJoin=a=>a.length<2?a.join(""):a.slice(0,-1).join(", ")+" and "+a[a.length-1];
const firstSent=s=>{const m=String(s).match(/^.*?[.!?](\s|$)/);return (m?m[0]:String(s)).trim();};
const ldTag=o=>`<script type="application/ld+json">${JSON.stringify(o).replace(/</g,"\\u003c")}<\/script>`;
function answerBlock(q,a){return `<div class="answer"><span class="answerq">${esc(q)}</span><p>${esc(a)}</p></div>`;}
function quickFacts(rows){rows=rows.filter(r=>r&&r[1]);if(!rows.length)return "";
  return `<aside class="qfacts" aria-label="Quick facts"><span class="seclabel">Quick facts</span><dl>${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join("")}</dl></aside>`;}
function qaBlock(list){list=list.filter(x=>x&&x[1]);if(list.length<2)return "";
  return `<section class="qa"><span class="seclabel">Good to know</span><h2>Questions travelers ask</h2>${list.slice(0,5).map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("")}</section>`+
    ldTag({"@context":"https://schema.org","@type":"FAQPage",mainEntity:list.slice(0,5).map(([q,a])=>({"@type":"Question",name:q,acceptedAnswer:{"@type":"Answer",text:a}}))});}
const afterH1=(html,ins)=>html.replace(/(<\/h1>)/,"$1"+ins);
const addEnd=(html,ins)=>html+ins;
const months=m=>monthsLabel(m);
const nextEvent=rid=>EVENTS.filter(e=>e.region===rid&&!e.sample&&!e.annual&&e.end>=isoDay(0)).sort((a,b)=>a.start.localeCompare(b.start))[0];
function isoDay(off){const d=new Date();d.setDate(d.getDate()+off);return d.toISOString().slice(0,10);}
