const evPath=e=>`/events/${slug(e.name)}/`;

/* ---------- share: link + Story / Feed cards + event cover (canvas, Travel Diary style) ---------- */
function utm(path,campaign){return `${SITE_URL}${path}?utm_source=share&utm_medium=social&utm_campaign=${encodeURIComponent(campaign)}`;}
function shareBox({title,sub,kind,path,cover=false,paid=false}){
  if(paid)return ""; /* no share cards for Featured or sponsored items */
  const d=`data-title="${esc(title)}" data-sub="${esc(sub||"")}" data-kind="${esc(kind)}" data-path="${esc(path)}"`;
  return `<div class="sharebox" ${d}><span class="seclabel">Share it</span><div class="crow">
    <button type="button" class="pill" data-share="link">Copy link</button>
    <button type="button" class="pill ghost" data-share="story">Story image</button>
    ${CO4_CONFIG.features.shareCardFeed?`<button type="button" class="pill ghost" data-share="feed">Feed image</button>`:""}
    ${cover?`<button type="button" class="pill ghost" data-share="cover">Download for Facebook event</button>`:""}</div></div>`;}
function wrapLines(ctx,text,maxW){const w=text.split(/\s+/),lines=[];let cur="";w.forEach(x=>{const t=cur?cur+" "+x:x;if(ctx.measureText(t).width>maxW&&cur){lines.push(cur);cur=x;}else cur=t;});if(cur)lines.push(cur);return lines;}
function clipWords(s,n){const w=String(s).split(/\s+/);return w.length<=n?s:w.slice(0,n).join(" ")+"…";}
function heroGrad(ctx,W,H){const g=ctx.createLinearGradient(W*.42,0,W*.58,H);[[0,"#0B7568"],[.38,"#138A57"],[.62,"#9BBF2A"],[.8,"#F1C50E"],[1,"#F0A01A"]].forEach(([o,c])=>g.addColorStop(o,c));return g;}
async function drawCard(kind,{title,sub,label}){
  const S={story:[1080,1920],feed:[1080,1350],cover:[1200,628]}[kind];const [W,H]=S;
  try{await Promise.all([document.fonts.load('700 100px "Oswald"'),document.fonts.load('600 40px "Libre Franklin"')]);}catch(e){}
  const c=document.createElement("canvas");c.width=W;c.height=H;const x=c.getContext("2d");
  x.fillStyle=heroGrad(x,W,H);x.fillRect(0,0,W,H);
  const pad=kind==="cover"?64:90,safeTop=kind==="story"?250:kind==="feed"?110:56;
  const hs=Math.round(H*(kind==="cover"?.105:.075));                 /* headline ≥ ~7% of height */
  x.fillStyle="#FFFFFF";x.font=`600 ${Math.round(hs*.32)}px "Oswald", "Arial Narrow", Arial, sans-serif`;
  x.fillText(String(label||"LOCAL LEGENDS MAP").toUpperCase().split("").join(String.fromCharCode(8202)),pad,safeTop+hs*.4);
  x.fillStyle="#ED7912";x.fillRect(pad,safeTop+hs*.62,hs*1.4,Math.max(8,hs*.08));
  x.font=`700 ${hs}px "Oswald", "Arial Narrow", Arial, sans-serif`;x.fillStyle="#FFFFFF";
  const lines=wrapLines(x,clipWords(title,9).toUpperCase(),W-pad*2).slice(0,kind==="cover"?2:4);
  let y=safeTop+hs*1.9;lines.forEach(l=>{x.fillText(l,pad,y);y+=hs*1.05;});
  if(sub){x.font=`600 ${Math.round(hs*.36)}px "Libre Franklin", Arial, sans-serif`;wrapLines(x,clipWords(sub,9),W-pad*2).slice(0,2).forEach(l=>{x.fillText(l,pad,y+hs*.05);y+=hs*.48;});}
  const foot=kind==="story"?H-250-30:H-(kind==="cover"?44:90);
  x.fillStyle="#111111";x.font=`700 ${Math.round(hs*(kind==="cover"?.3:.34))}px "Oswald", Arial, sans-serif`;
  x.fillText("LOCALLEGENDSMAP.COM · VOTED BY LOCALS",pad,foot);
  return c;}
document.addEventListener("click",async e=>{const b=e.target.closest("[data-share]");if(!b)return;const box=b.closest(".sharebox");if(!box)return;
  const {title,sub,kind,path}=box.dataset;const how=b.dataset.share;const url=utm(path,how==="link"?"link":how+"-card");
  if(how==="link"){try{if(navigator.share){await navigator.share({title:title+" · The Local Legends Map",url});return;}await navigator.clipboard.writeText(url);toast("Link copied. Paste it in your group chat.");}catch(err){toast(url);}return;}
  const c=await drawCard(how,{title,sub,label:"Local Legends Map · "+kind});
  c.toBlob(bl=>{const a=document.createElement("a");a.href=URL.createObjectURL(bl);a.download=`local-legends-${slug(title)}-${how}.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000);
    toast(how==="cover"?"Event cover saved (1200×628). Add it to your Facebook event.":`Saved a ${how==="story"?"Story (1080×1920)":"Feed (1080×1350)"} image. Link: ${url}`);},"image/png");});

/* ---------- sponsor slots (labeled, never ranked, hidden when empty) ---------- */
function slotPresented(key,label){const s=SPONSORS.presentedBy[key]||SPONSORS.seasonal[key];
  if(!CO4_CONFIG.features.sponsorSlots)return "";
  return s?`<div class="sponsorslot"><span class="featag">Sponsored</span><span>Presented by <a href="${esc(s.url)}" target="_blank" rel="noopener sponsored"><b>${esc(s.name)}</b></a>${s.line?" · "+esc(s.line):""}</span></div>`
    :`<p class="sponsorlink"><a href="#sponsors">Sponsor this ${esc(label)} →</a></p>`;}

/* ---------- answer-ready blocks for region, dish, trail, road trip and event pages ---------- */
function regionCO4(r){const nm=r.name;const trails=trailsForRegion(r.id);const evs=EVENTS.filter(e=>e.region===r.id&&!e.sample);
  const dishes=r.dishes.map(d=>d.n);const d0=r.dishes[0];
  const spots=[...new Set(r.dishes.flatMap(d=>d.s.filter(s=>!/\(brand\)/.test(s)).map(spotName)))].slice(0,3);
  const a=answerText([`The local legendary foods of ${nm} are ${listJoin(dishes)}.`,firstSent(d0.d),spots.length?`Find them at places like ${listJoin(spots)}.`:"",
    `Towns to know: ${listJoin(r.towns.slice(0,4))}.`,trails.length?`${trails.length} ${trails.length===1?"crawl or trail runs":"crawls and trails run"} through the region, voted by locals on Local Legends Map.`:"Missing a local favorite? Members can nominate it."]);
  const facts=quickFacts([["Region",esc(nm)],["Towns",esc(r.towns.slice(0,6).join(", "))],["Signature foods",r.dishes.map((d,i)=>`<a href="${dishHref(r.id,i)}">${esc(d.n)}</a>`).join(", ")],
    ["Crawls & trails",trails.length?trails.slice(0,4).map(t=>`<a href="${t.href}">${esc(t.name)}</a>`).join(", "):""],["Food events",evs.length?evs.map(e=>`<a href="${evHref(e)}">${esc(e.name)}</a> (${esc(evDate(e))})`).join(", "):""]]);
  const qa=qaBlock([[`What should I eat first in ${nm}?`,`Start with ${d0.n}. ${firstSent(d0.d)}`],
    d0.s.length?[`Where do locals get ${d0.n}?`,`Classic spots include ${listJoin(d0.s.map(spotName).slice(0,4))}.`]:null,
    trails.length?[`Are there food trails in ${nm}?`,`Yes: ${listJoin(trails.slice(0,3).map(t=>t.name))}.`]:null,
    evs.length?[`When are the food festivals in ${nm}?`,evs.slice(0,3).map(e=>`${e.name}: ${evDate(e)}.`).join(" ")]:null]);
  const ld=ldTag({"@context":"https://schema.org","@type":"ItemList",name:`Local legendary foods of ${nm}`,itemListElement:r.dishes.map((d,i)=>({"@type":"ListItem",position:i+1,name:d.n,url:`${SITE_URL}${areaPath(r.id)}${dslug(d.n)}/`}))});
  return {answer:answerBlock(`What are the local legendary foods of ${nm}?`,a),tail:`<div class="co4tail">${facts}${qa}${ld}${shareBox({title:`Local legendary foods of ${nm}`,sub:dishes.slice(0,3).join(" · "),kind:"Region",path:`${areaPath(r.id)}`})}</div>`};}
function dishCO4(r,i){const d=r.dishes[+i];const sp=d.s.filter(s=>!/\(brand\)/.test(s));const brands=d.s.filter(s=>/\(brand\)/.test(s)).map(spotName);
  const evs=EVENTS.filter(e=>e.dish&&e.dish[0]===r.id&&e.dish[1]===+i);
  const origin=(d.d.match(/[^.]*\b(invented|created|born|first (made|served|sold)|originated|dates? (back )?to)\b[^.]*\./i)||[])[0];
  const a=answerText([sp.length?`Locals get ${d.n} in ${r.name} at ${listJoin(sp.slice(0,4).map(s=>`${spotName(s)} (${spotTown(s,r)})`))}.`:brands.length?`${d.n} is a ${r.name} brand; look for ${listJoin(brands)} in local stores.`:`No classic ${d.n} spots in ${r.name} are on file yet; members can nominate one.`,
    firstSent(d.d),d.d.split(/(?<=\.)\s+/)[1]||"",evs.length?`It gets its own celebration: ${evs[0].name}.`:"","Places are voted by locals on Local Legends Map."]);
  const facts=quickFacts([["Dish",esc(d.n)],["Region",`<a href="#r-${r.id}">${esc(r.name)}</a>`],["Where to get it",sp.length?esc(sp.map(spotName).join(", ")):brands.length?esc(brands.join(", "))+" (brand)":""],
    ["Celebrated at",evs.length?evs.map(e=>`<a href="${evHref(e)}">${esc(e.name)}</a>`).join(", "):""],["Season",isSeasonal(`d-${r.id}-${i}`)?months(SEASON[`d-${r.id}-${i}`].m):""]]);
  const qa=qaBlock([sp.length?[`Where do locals get ${d.n} in ${r.name}?`,`${listJoin(sp.slice(0,4).map(s=>`${spotName(s)} in ${spotTown(s,r)}`))}.`]:null,
    origin?[`Where was ${d.n} invented?`,origin.trim()]:null,
    evs.length?[`Is there a festival for ${d.n}?`,evs.map(e=>`${e.name} in ${e.town}: ${evDate(e)}.`).join(" ")]:null,
    [`What else do locals eat in ${r.name}?`,`${listJoin(r.dishes.filter((x,j)=>j!=+i).map(x=>x.n))||"More is coming as members add it"}.`]]);
  const ld=sp.length?ldTag({"@context":"https://schema.org","@type":"ItemList",name:`Where locals get ${d.n} in ${r.name}`,itemListElement:sp.map((s,k)=>({"@type":"ListItem",position:k+1,item:{"@type":"Restaurant",name:spotName(s),address:{"@type":"PostalAddress",addressLocality:spotTown(s,r),addressRegion:"NY"}}}))}):"";
  return {answer:answerBlock(`Where do locals get ${d.n} in ${r.name}?`,a),tail:`<div class="co4tail">${facts}${qa}${ld}${shareBox({title:d.n,sub:r.name,kind:"Local legend",path:`${areaPath(r.id)}${dslug(d.n)}/`})}</div>`};}
function trailCO4(id){const info=allTrails().find(x=>x.id===id);if(!info)return null;const t=info.t;const road=info.kind==="Road trip";
  const stops=road?t.stops.map(([rid,what])=>({n:what,t:R(rid).name,o:""})):t.stops;const fmt=(info.fmt||"Trail").toLowerCase();const paid=!!SPONSOR[id];
  const a=answerText([`The ${t.name.replace(/^The /,"")} is a ${fmt==="road trip"?"multi-day road trip":fmt} with ${stops.length} stops: ${listJoin(stops.slice(0,6).map(s=>road?s.n:`${s.n} (${s.t})`))}.`,
    isSeasonal(id)?`It runs ${months(SEASON[id].m)}. ${SEASON[id].why||""}`:"",t.tip?`Tip: ${t.tip}`:"","Stops and order are voted by locals on Local Legends Map."]);
  const orders=stops.filter(s=>s.o).slice(0,3).map(s=>`${s.n}: ${s.o.replace(/\.$/,"")}.`);
  const facts=quickFacts([["Type",esc(info.fmt||"Trail")],["Area",esc(info.area)],["Stops",String(stops.length)],["Season",isSeasonal(id)?esc(months(SEASON[id].m)):""],["Getting around",esc(t.mode||"")],
    ["Signature order",orders[0]?esc(orders[0]):""],["Run by",info.org?esc(info.org):info.by?esc(info.by)+" (example)":""]]);
  const qa=qaBlock([isSeasonal(id)?[`Is the ${t.name.replace(/^The /,"")} open year-round?`,`No. It runs ${months(SEASON[id].m)}. ${SEASON[id].why||""}`.trim()]:null,
    isSeasonal(id)?["When is the best time to go?",`In season: ${months(SEASON[id].m)}. ${inSeason(id)?"It's on now.":"It's back in "+backIn(id)+"."}`]:null,
    orders.length?["What do locals order?",orders.join(" ")]:null,
    [`How many stops are on the ${fmt}?`,`${stops.length} stops${t.meta?" · "+t.meta:""}.`],
    t.tip?["Any tips before I go?",t.tip]:null]);
  const ld=ldTag({"@context":"https://schema.org","@type":"TouristTrip",name:t.name,description:t.d,touristType:"Food travelers",itinerary:{"@type":"ItemList",numberOfItems:stops.length,itemListElement:stops.map((s,k)=>({"@type":"ListItem",position:k+1,item:road?{"@type":"Place",name:s.n}:{"@type":"Place",name:s.n,address:{"@type":"PostalAddress",addressLocality:s.t,addressRegion:"NY"},geo:{"@type":"GeoCoordinates",latitude:s.la,longitude:s.lo}}}))}});
  return {answer:answerBlock(`What's on the ${t.name.replace(/^The /,"")}?`,a),tail:`<div class="co4tail">${facts}${qa}${ld}${slotPresented(id,fmt)}${shareBox({title:t.name,sub:`${stops.length} stops · ${info.area}`,kind:info.fmt||"Trail",path:info.path})}</div>`};}

/* ---------- event pages ---------- */
PAGES_EXTRA.event=id=>{const e=EVENTS.find(x=>x.id===id&&!x.sample);if(!e)return PAGES.notfound();const r=R(e.region);
  const when=e.annual?e.annual:evDate(e)+(e.start.slice(0,4)!==String(new Date().getFullYear())?", "+e.start.slice(0,4):", "+e.start.slice(0,4));
  const a=answerText([`${e.name} ${e.annual?"happens "+e.annual.toLowerCase():"runs "+evDate(e)+", "+e.start.slice(0,4)} in ${e.town}${e.time?", "+e.time:""}.`,e.d,e.org?`It's hosted by ${e.org}.`:"",
    `It's in ${r.name}, known for ${listJoin(r.dishes.slice(0,3).map(d=>d.n))}.`,"Check the organizer's site before you go; details can change."]);
  const facts=quickFacts([["Event",esc(e.name)],["When",esc(when)],["Where",esc(e.town)],["Time",esc(e.time||"")],["Type",esc(e.type)],["Hosted by",esc(e.org||"")],["Region",`<a href="#r-${r.id}">${esc(r.name)}</a>`],["Source",esc(e.src||"")],
    ["The food",e.dish?`<a href="${dishHref(e.dish[0],e.dish[1])}">${esc(R(e.dish[0]).dishes[e.dish[1]].n)}</a>`:""]]);
  const qa=qaBlock([[`When is ${e.name}?`,e.annual?`${e.annual}. ${/announced/.test(e.d)?"Next year's dates are to be announced.":""}`.trim():`${evDate(e)}, ${e.start.slice(0,4)}${e.time?", "+e.time:""}.`],
    [`Where is ${e.name}?`,`${e.town}, in ${r.name}.`],e.org?["Who runs it?",e.org+"."]:null,
    [`What should I eat while I'm in ${r.name.split(" & ")[0]}?`,`Locals would point you to ${listJoin(r.dishes.slice(0,3).map(d=>d.n))}.`]]);
  const ld=e.annual?"":ldTag({"@context":"https://schema.org","@type":"Event",name:e.name,startDate:e.start,endDate:e.end,eventStatus:"https://schema.org/EventScheduled",eventAttendanceMode:"https://schema.org/OfflineEventAttendanceMode",
    description:e.d,location:{"@type":"Place",name:e.town,address:{"@type":"PostalAddress",addressLocality:e.town.replace(/\s*\(.*\)/,""),addressRegion:"NY",addressCountry:"US"}},...(e.org?{organizer:{"@type":"Organization",name:e.org}}:{})});
  return {path:evPath(e),title:e.name,html:`
  ${crumbs([["Home","#home"],["Events","#events"],[e.name,""]])}
  <div class="pagehead"><span class="eyebrow">${esc(e.type)} · ${esc(when)}</span><h1>${esc(e.name)}</h1>${answerBlock(`When is ${e.name} and what's there?`,a)}${seasonBadge(e.id)}</div>
  <div class="split"><div class="mapbox" id="mapslot"></div><div>${facts}</div></div>
  ${qa}${ld}${shareBox({title:e.name,sub:`${e.annual||evDate(e)} · ${e.town.replace(/\s*\(.*\)/,"")}`,kind:"Event",path:evPath(e),cover:true,paid:!!e.promo})}
  <section class="band"><div class="sec-head"><h2>More food events</h2><a href="#events">Full calendar →</a></div><div class="nlist three">${EVENTS.filter(x=>x.id!==e.id&&!x.sample).slice(0,3).map(evCard).join("")}</div></section>`,
  after(){const [x,y]=P(r.lat,r.lon);const w=380,h=w*540/690;$("#mapslot").appendChild(nyMap({active:[r.id],zoom:[x-w/2,y-h/2,w,h]}));}};};

/* ---------- This weekend ---------- */
function weekendEvents(rid){const a=isoDay(0),b=isoDay(7);
  return EVENTS.filter(e=>!e.sample&&!e.annual&&e.start<=b&&e.end>=a&&(rid==="all"||e.region===rid)).sort((x,y)=>x.start.localeCompare(y.start)).slice(0,6);}
function weekendCards(rid){const list=weekendEvents(rid);const sp=SPONSORS.eventSpotlight&&CO4_CONFIG.features.sponsorSlots?SPONSORS.eventSpotlight:null;
  const spot=sp?`<a class="wkcard spotlight" href="${esc(sp.url)}" target="_blank" rel="noopener sponsored"><span class="featag">Sponsored</span><b>${esc(sp.name)}</b><span>Event spotlight</span></a>`:"";
  return list.length?spot+list.map(e=>{const r=R(e.region);return `<a class="wkcard" href="${evHref(e)}"><span class="wkdate">${esc(evDate(e))}</span><b>${esc(e.name)}</b><span>${esc(e.town.replace(/\s*\(.*\)/,""))} · ${esc(r.name)}</span></a>`;}).join("")
    :spot+`<p class="wkempty">Nothing on the calendar in the next 7 days${rid==="all"?"":" in "+esc(R(rid).name)}. <a href="#events">See what's coming up →</a></p>`;}
function weekendStrip(){return `<section class="band weekend" id="weekend"><div class="sec-head"><div><span class="seclabel">Next 7 days</span><h2>This weekend</h2></div>
  <label class="f wkreg">Near<select id="wkreg"><option value="all">All of New York</option>${REGIONS.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join("")}</select></label></div>
  <div class="wkrow" id="wkrow">${weekendCards("all")}</div><p class="seeall"><a href="#events">See all events →</a></p></section>`;}
function bindWeekend(){const s=$("#wkreg");if(!s)return;const saved=LS.get("llm_region");if(saved&&R(saved)){s.value=saved;$("#wkrow").innerHTML=weekendCards(saved);}
  s.addEventListener("change",()=>{LS.set("llm_region",s.value);$("#wkrow").innerHTML=weekendCards(s.value);});}

/* ---------- Travel Diary home ---------- */
function regionRowLabel(r){const e=nextEvent(r.id);if(e)return evDate(e);const t=trailsForRegion(r.id).find(x=>isSeasonal(x.id)&&x.inSeason);if(t)return "In season";return `${r.dishes.length} legends`;}
function destRows(list){return `<ul class="destrows">${list.map(r=>`<li><a href="#r-${r.id}"><span class="dlabel">${esc(regionRowLabel(r))}</span><span class="dname">${esc(r.name)}</span><span class="ddish">${r.dishes.map(d=>esc(d.n)).join(" · ")}</span><span class="darrow" aria-hidden="true">→</span></a></li>`).join("")}</ul>`;}
function timeline(stops){return `<ol class="timeline">${stops.map((s,k)=>`<li><span class="tdot" aria-hidden="true"></span><span class="tlabel2">Stop ${k+1}${s.t?" · "+esc(s.t):""}</span><b>${esc(s.n)}</b>${s.o?`<small>${esc(s.o)}</small>`:""}</li>`).join("")}</ol>`;}
/* === CO6 === seasonal home hero: winter Dec–Feb, spring Mar–May, summer Jun–Aug, fall Sep–Nov */
function heroSeason(){const m=new Date().getMonth()+1;return m===12||m<=2?"winter":m<=5?"spring":m<=8?"summer":"fall";}
document.documentElement.dataset.season=heroSeason();
function diaryHome(){const regs=REGIONS.map(r=>[r,trailsForRegion(r.id).length+(nextEvent(r.id)?3:0)]).sort((a,b)=>b[1]-a[1]).map(a=>a[0]);
  const top=allTrails().filter(t=>t.inSeason).slice(0,6);
  const day=allTrails().find(t=>t.kind==="Official trail"&&t.inSeason&&t.t.stops.length>=3)||allTrails().find(t=>t.kind==="Official trail");
  const seasons=CO4_CONFIG.features.seasonalPages?activeSeasons():[];const fall=seasons.find(s=>s.id==="fall")||seasons[0];
  return {path:"/",title:"HOME",html:`
  <section class="diaryhero season-${heroSeason()}">
    <div class="hero-copy"><span class="kicker">The foods places are famous for · All 50 states</span>
      <h1>Eat like you live there.</h1>
      <p class="intro">We help you find the local culinary legends and how they celebrate them.</p>
      <form class="search big" id="homeSearch" role="search"><input id="hq" list="townlist" placeholder="Where are you headed?" aria-label="Where are you headed? Search a city, town or dish" autocomplete="off"><button class="btn" type="submit">Find food</button><div class="search-msg" id="hmsg" aria-live="polite"></div></form>
      <div class="qchips" aria-label="Quick picks"><a href="#theme-wings">Wings</a><a href="#theme-pizza">Pizza</a>${fall?`<a href="#season-${fall.id}">${fall.id==="fall"?"Fall festivals":esc(fall.chip)}</a>`:""}<button type="button" data-scrollto="weekend">This weekend</button>${regs.slice(0,4).map(r=>`<a href="#r-${r.id}">${esc(r.name.split(" & ")[0])}</a>`).join("")}</div>
      <div class="crow herobtns"><a class="pill white" href="#ny">Explore the map</a><a class="pill outline" href="#guide">Build a crawl</a></div>
    </div>
    <div class="mapframe"><div class="usmap" id="usmap" aria-label="Pick a state"></div><a class="statepick" href="#ny"><span>Pick a state</span><b>New York</b><small>More states coming soon</small></a></div>
  </section>
  ${CO4_CONFIG.features.thisWeekend?weekendStrip():""}
  <section class="band"><span class="seclabel">Region by region</span><div class="sec-head"><h2>Local legendary foods</h2><a href="#ny">All of New York →</a></div>${destRows(regs.slice(0,8))}</section>
  <section class="band"><span class="seclabel">Crawls & road trips</span><div class="sec-head"><h2>Grab the crew. Hit the road.</h2><a href="#trails">All trails →</a></div><div class="tgrid">${top.map(trailCard).join("")}</div></section>
  ${day?`<section class="band oneday"><div><span class="seclabel">One day like a local</span><h2>${esc(day.name)}</h2><p>${esc(day.d)}</p>
    <div class="crow"><a class="pill" href="${day.href}">Read the ${esc((day.fmt||"trail").toLowerCase())}</a><a class="pill ghost" href="#guide">Save this day as a crawl</a></div></div>${timeline(day.t.stops)}</section>`:""}
  ${CO4_CONFIG.features.localQuotes?`<section class="band quotes"><span class="seclabel">What locals say</span><div class="quotegrid" id="quotegrid"></div></section>`:""}
  <section class="band homemapband"><span class="seclabel">The map</span><div class="sec-head"><h2>Explore New York</h2><a href="#ny">All 23 regions →</a></div>
    <p class="maptip">Tap a region to see its local legendary foods. Drag to move, pinch or scroll to zoom.</p><div class="mapbox" id="homemap"></div></section>
  <section class="band"><span class="seclabel">On the calendar</span><div class="sec-head"><h2>Coming up</h2><a href="#events">Full calendar →</a></div><div class="nlist three">${EVENTS.filter(e=>!e.annual&&!e.sample&&e.end>=isoDay(0)).concat(EVENTS.filter(e=>e.annual)).slice(0,3).map(evCard).join("")}</div></section>
  <section class="band"><span class="seclabel">Regional delights</span><div class="sec-head"><h2>Know these by heart</h2><a href="#cravings">See them all →</a></div>
    <div class="dishstrip">${[["albany",1],["plattsburgh",0],["binghamton",0],["rochester",0],["adirondacks",0],["northcountry",0]].map(([rid,i])=>{const r=R(rid),d=r.dishes[i];return `<a class="dcard" href="${dishHref(rid,i)}"><span class="where">${esc(r.name)}</span><b>${esc(d.n)}</b><p>${esc(d.d.split(". ")[0])}.</p></a>`}).join("")}</div></section>
  <section class="band moreband"><span class="seclabel">More to explore</span><div class="morelinks">
    <a href="#plan"><b>Plan a trip</b><span>Pick a region and dates; we'll line up the food</span></a>
    ${seasons.map(s=>`<a href="#season-${s.id}"><b>${esc(s.n)}</b><span>${esc(s.blurb)}</span></a>`).join("")}
    <a href="#vote"><b>Up for a Vote</b><span>Nominate a local legend, pick a side in a food fight</span></a>
    <a href="#news"><b>Food news</b><span>Festivals, openings and closings</span></a>
    <a href="#f-hotdogs"><b>The Hot Dogs of New York</b><span>Nine dogs, nine answers</span></a>
    <a href="#pizza-ny"><b>The Pizza Styles of New York</b><span>From the folded slice to Buffalo cup-and-char</span></a>
    <a href="#f-factories"><b>Factory tours</b><span>Watch it get made, then taste it</span></a>
    <a href="#organizers"><b>Run a festival or food tour?</b><span>Post events free, host a crawl</span></a>
    <a href="#list"><b>Own a legendary spot?</b><span>Get on the Trail</span></a></div></section>`,
  after(){usMap();$("#homemap").appendChild(nyMap({}));bindSearch("#homeSearch","#hq","#hmsg");bindWeekend();setHeroH();}};}
function setHeroH(){const h=document.querySelector(".diaryhero");if(!h)return;const w=document.querySelector("#weekend");
  /* gradient ends just below the This weekend panel, so the yellow/orange tail never sits behind text */
  const end=w?w.getBoundingClientRect().bottom+scrollY+28:(h.getBoundingClientRect().bottom+scrollY)/0.58;document.body.style.setProperty("--heroH",Math.round(end)+"px");}
try{document.fonts.ready.then(()=>setHeroH());document.fonts.addEventListener("loadingdone",()=>setHeroH());}catch(e){}
window.addEventListener("load",()=>setHeroH());
window.addEventListener("resize",()=>{clearTimeout(setHeroH._t);setHeroH._t=setTimeout(setHeroH,120);});
document.addEventListener("click",e=>{const b=e.target.closest("[data-scrollto]");if(!b)return;const t=document.getElementById(b.dataset.scrollto);if(t)t.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});});

/* ---------- seasonal guides (built from season tags in the data) ---------- */
const SEASON_GUIDES=[
  {id:"fall",n:"Fall food trips in New York",chip:"Fall festivals",path:"/seasons/fall-food-trips-new-york/",m:[9,10,11],kw:/apple|cider|pumpkin|harvest|doughnut|donut/i,blurb:"Orchards, cider doughnuts and harvest festivals"},
  {id:"summer",n:"Summer food festivals in New York",chip:"Summer festivals",path:"/seasons/summer-food-festivals-new-york/",m:[6,7,8],kw:/ice cream|custard|clam|corn on the cob|sauerkraut|spiedie/i,blurb:"Walk-up stands and August festival weekends"},
  {id:"holiday",n:"Holiday food traditions in New York",chip:"Holiday treats",path:"/seasons/holiday-food-traditions-new-york/",m:[11,12],kw:/christmas|holiday|peppermint pig|candy cane|fruitcake/i,blurb:"The treats locals buy once a year"},
  {id:"lent",n:"Lent fish fry guide to New York",chip:"Fish fry",path:"/seasons/lent-fish-fry-new-york/",m:[2,3,4],kw:/fish fry|fried fish|haddock/i,blurb:"Friday fish fries, parish halls and taverns"},
  {id:"maple",n:"Maple season in New York",chip:"Maple",path:"/seasons/maple-season-new-york/",m:[3,4],kw:/maple/i,blurb:"Sugar shacks and pancake breakfasts"}];
function seasonMatch(s){const hit=m=>m.some(x=>s.m.includes(x));
  const trails=allTrails().filter(t=>isSeasonal(t.id)&&hit(SEASON[t.id].m));
  const events=EVENTS.filter(e=>!e.sample&&(isSeasonal(e.id)?hit(SEASON[e.id].m):(!e.annual&&s.m.includes(+e.start.slice(5,7)))));
  const dishes=[];REGIONS.forEach(r=>r.dishes.forEach((d,i)=>{if(s.kw.test(d.n+" "+d.d))dishes.push({r,d,i});}));
  return {trails,events,dishes};}
function activeSeasons(){return SEASON_GUIDES.filter(s=>{const m=seasonMatch(s);return m.trails.length+m.events.length+m.dishes.length>0;});}
PAGES_EXTRA.season=id=>{const s=SEASON_GUIDES.find(x=>x.id===id);if(!s||!CO4_CONFIG.features.seasonalPages)return PAGES.notfound();const m=seasonMatch(s);if(!(m.trails.length+m.events.length+m.dishes.length))return PAGES.notfound();
  const a=answerText([`${s.n.replace(/ in New York| to New York/,"")} run ${months(s.m)}.`,m.trails.length?`Start with ${listJoin(m.trails.slice(0,3).map(t=>t.name))}.`:"",
    m.events.length?`On the calendar: ${listJoin(m.events.slice(0,3).map(e=>`${e.name} (${e.annual||evDate(e)})`))}.`:"",
    m.dishes.length?`Seasonal tastes to look for: ${listJoin(m.dishes.slice(0,4).map(x=>`${x.d.n} in ${x.r.name}`))}.`:"","Everything here is voted by locals on Local Legends Map; check hours before you drive."]);
  const ld=ldTag({"@context":"https://schema.org","@type":"ItemList",name:s.n,itemListElement:[...m.trails.map(t=>({name:t.name,url:SITE_URL+t.path})),...m.events.map(e=>({name:e.name,url:SITE_URL+evPath(e)}))].map((x,k)=>({"@type":"ListItem",position:k+1,...x}))});
  return {path:s.path,title:s.n,html:`
  ${crumbs([["Home","#home"],["Plan a trip","#plan"],[s.n,""]])}
  <div class="pagehead"><span class="eyebrow">Seasonal guide · ${esc(months(s.m))}</span><h1>${esc(s.n)}</h1>${answerBlock(`When are ${s.n.toLowerCase().replace(/ in new york| to new york/,"")} and where should I go?`,a)}</div>
  ${SPONSORS.seasonal[id]?`<div class="sponsorbanner">${slotPresented(id,"guide")}</div>`:""}
  ${m.trails.length?`<section class="band"><span class="seclabel">Crawls & trails</span><div class="sec-head"><h2>Follow the season</h2></div><div class="tgrid">${m.trails.map(trailCard).join("")}</div></section>`:""}
  ${m.events.length?`<section class="band"><span class="seclabel">Festivals</span><div class="sec-head"><h2>On the calendar</h2><a href="#events">Full calendar →</a></div><div class="nlist three">${m.events.map(evCard).join("")}</div></section>`:""}
  ${m.dishes.length?`<section class="band"><span class="seclabel">Seasonal tastes</span><div class="sec-head"><h2>What to eat</h2></div><div class="dishstrip">${m.dishes.slice(0,8).map(x=>`<a class="dcard" href="${dishHref(x.r.id,x.i)}"><span class="where">${esc(x.r.name)}</span><b>${esc(x.d.n)}</b><p>${esc(firstSent(x.d.d))}</p></a>`).join("")}</div></section>`:""}
  ${ld}${SPONSORS.seasonal[id]?"":slotPresented(id,"guide")}${shareBox({title:s.n,sub:months(s.m),kind:"Seasonal guide",path:s.path})}`};};

/* ---------- Plan a Trip ---------- */
function planResults(rid,from,to){const r=R(rid);if(!r)return "";const mm=new Set();for(let d=new Date(from+"T12:00:00");d<=new Date(to+"T12:00:00")&&mm.size<12;d.setDate(d.getDate()+1))mm.add(d.getMonth()+1);
  const evs=EVENTS.filter(e=>!e.sample&&!e.annual&&e.start<=to&&e.end>=from&&e.region===rid);
  const nearEvs=EVENTS.filter(e=>!e.sample&&!e.annual&&e.start<=to&&e.end>=from&&e.region!==rid).slice(0,3);
  const trails=trailsForRegion(rid);const seas=allTrails().filter(t=>isSeasonal(t.id)&&SEASON[t.id].m.some(x=>mm.has(x))&&t.regions.includes(rid));
  return `<div class="planout">
    <section><span class="seclabel">Events in your window</span><h2>${evs.length?`${evs.length} on while you're there`:"No events on file for those dates"}</h2>${evs.length?`<div class="nlist">${evs.map(evCard).join("")}</div>`:nearEvs.length?`<p>Elsewhere in New York those days: ${nearEvs.map(e=>`<a href="${evHref(e)}">${esc(e.name)}</a> (${esc(evDate(e))})`).join(", ")}.</p>`:`<p class="muted">Try other dates, or <a href="#events">see the full calendar</a>.</p>`}</section>
    <section><span class="seclabel">Legends worth a stop</span><h2>What to eat in ${esc(r.name)}</h2>${destRows([r])}<ul class="planlist">${r.dishes.map((d,i)=>`<li><a href="${dishHref(rid,i)}"><b>${esc(d.n)}</b></a> · ${esc(d.s.slice(0,3).map(spotName).join(", ")||"spots wanted")}</li>`).join("")}</ul></section>
    ${seas.length?`<section><span class="seclabel">In season while you're there</span><h2>Only this time of year</h2><div class="tgrid">${seas.map(trailCard).join("")}</div></section>`:""}
    <section><span class="seclabel">Crawls & trails nearby</span><h2>${trails.length?"Follow a trail":"No trails here yet"}</h2>${trails.length?`<div class="tgrid">${trails.slice(0,6).map(trailCard).join("")}</div>`:`<p class="muted"><a href="#guide">Build the first one</a>.</p>`}</section>
    <div class="crow noprint"><a class="pill" href="#guide">Save as a crawl</a><button class="pill ghost" type="button" id="planshare">Share this plan</button><button class="pill ghost" type="button" onclick="window.print()">Print</button></div></div>`;}
PAGES_EXTRA.plan=()=>{if(!CO4_CONFIG.features.planTrip)return PAGES.notfound();const q=new URLSearchParams(location.search);const rid=R(q.get("r"))?q.get("r"):(R(LS.get("llm_region")||"")?LS.get("llm_region"):"");
  const from=q.get("from")||isoDay(0),to=q.get("to")||isoDay(2);const seasons=CO4_CONFIG.features.seasonalPages?activeSeasons():[];
  return {path:"/plan/",title:"Plan a food trip",html:`
  ${crumbs([["Home","#home"],["Plan a trip",""]])}
  <div class="pagehead"><span class="eyebrow">Trip planner · no account needed</span><h1>Plan a food trip</h1>${answerBlock("How do I plan a food trip in New York?","Pick the region you're headed to and your dates. We'll pull the festivals on while you're there, the crawls and trails nearby, anything only in season that week and the local legends worth a stop. Save it as a crawl, share the link with your crew or print it for the car.")}</div>
  <form class="planform noprint" id="planform"><label class="f">Region<select name="r" required><option value="">Pick a region</option>${REGIONS.map(r=>`<option value="${r.id}" ${r.id===rid?"selected":""}>${esc(r.name)}</option>`).join("")}</select></label>
    <label class="f">From<input type="date" name="from" value="${from}" required></label><label class="f">To<input type="date" name="to" value="${to}" required></label><button class="pill" type="submit">Plan it</button><p class="ferr" id="planerr" aria-live="polite"></p></form>
  <div id="planbox">${rid?planResults(rid,from,to):""}</div>
  ${seasons.length?`<section class="band noprint"><span class="seclabel">Seasonal guides</span><div class="sec-head"><h2>Go when it's good</h2></div><div class="morelinks">${seasons.map(s=>`<a href="#season-${s.id}"><b>${esc(s.n)}</b><span>${esc(months(s.m))} · ${esc(s.blurb)}</span></a>`).join("")}</div></section>`:""}`,
  after(){const f=$("#planform"),box=$("#planbox"),err=$("#planerr");
    const run=()=>{const r=f.r.value,a=f.from.value,b=f.to.value;if(!r){err.textContent="Pick a region.";return;}if(!a||!b||b<a){err.textContent="Check your dates: the end can't be before the start.";return;}
      err.textContent="";LS.set("llm_region",r);const qs=new URLSearchParams({r,from:a,to:b}).toString();history.replaceState(null,"",location.pathname+"?"+qs+location.hash);box.innerHTML=planResults(r,a,b);};
    f.addEventListener("submit",e=>{e.preventDefault();run();});
    box.addEventListener("click",async e=>{if(e.target.id!=="planshare")return;const url=`${SITE_URL}/plan/${location.search}${location.search?"&":"?"}utm_source=share&utm_medium=social&utm_campaign=plan`;
      try{if(navigator.share){await navigator.share({title:"Our food trip · The Local Legends Map",url});return;}await navigator.clipboard.writeText(url);toast("Plan link copied. Your crew sees the same picks.");}catch(x){toast(url);}});}};};

