  <section class="band"><span class="seclabel">Slots</span><h2>Ways to sponsor</h2><div class="slotgrid">${slots.map(([n,d,p])=>`<div class="slotcard"><span class="featag">Labeled</span><h3>${n}</h3><p>${d}</p><span class="price">${p}</span></div>`).join("")}</div>
    <p class="muted">Every paid placement is labeled "Featured" or "Sponsored." No outside ad networks. Audience numbers will be shared here once the site has real ones.</p></section>
