const STYLES_NEXT=[["Detroit-Style","Michigan"],["Chicago Deep Dish","Illinois"],["Chicago Tavern-Style","Illinois"],["New Haven Apizza","Connecticut"],["Trenton Tomato Pie","New Jersey"],["Old Forge Pizza","Pennsylvania"],["St. Louis-Style","Missouri"],["Ohio Valley Pizza","Ohio & West Virginia"],["Quad Cities Pizza","Iowa & Illinois"]];
const stylesIn=(cat,st)=>STYLES.filter(s=>s.cat===cat&&s.st===st);
function styleDish(s){if(!s.dish)return null;const r=R(s.dish[0]);const i=r?r.dishes.findIndex(d=>d.n===s.dish[1]):-1;return i<0?null:{r,i,d:r.dishes[i]};}
function styleSpots(s){const out=[],seen=new Set();const sd=styleDish(s);const add=(n,t)=>{const k=n.toLowerCase();if(!seen.has(k)){seen.add(k);out.push([n,t]);}};
  if(sd)sd.d.s.filter(sp=>!/\(brand\)/.test(sp)).forEach(sp=>add(spotName(sp),spotTown(sp,sd.r)));
  const tr=FOOD_CATS[s.cat].trail&&TRAILS.find(t=>t.id===FOOD_CATS[s.cat].trail);
  (s.tstops||[]).forEach(n=>{const st=tr&&tr.stops.find(x=>x.n===n);if(st)add(st.n,st.t);});return out;}
const styleText=s=>{const sd=styleDish(s);return s.d||(sd?sd.d.d:"");};
const styleHref=s=>{const sd=styleDish(s);return sd?dishHref(sd.r.id,sd.i):`#r-${s.rid}`;};
function pizzaSVG(o){const ink="var(--ink)",crust="#E2B572",crustD="#C98F45",sauce="#C8452C",cheese="#F5D47A",mozz="#FFF8E6",romano="#FFFFFF";
  let s="";const dots=(pts,r,fill)=>pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}"/>`).join("");
  if(o.shape==="round"||o.shape==="small"){const R0=o.shape==="small"?27:39,cx=60,cy=45,rim=o.thick?7:o.edge?3.5:5,ri=R0-rim;
    s+=`<circle cx="${cx}" cy="${cy}" r="${R0}" fill="${crust}" stroke="${ink}" stroke-width="2"/>`;
    s+=`<circle cx="${cx}" cy="${cy}" r="${ri}" fill="${o.cheese?cheese:sauce}"/>`;
    if(o.mozz)s+=dots([[48,33],[70,36],[56,52],[75,55],[44,56],[62,28]],5.5,mozz);
    if(o.romano)s+=dots([[46,34],[58,30],[71,38],[52,47],[66,50],[77,46],[48,58],[60,62],[72,60],[40,46]],1.6,romano);
    if(o.cups)s+=[[47,34],[67,32],[57,47],[75,50],[45,55],[63,62]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" fill="#B13A26" stroke="#7E2416" stroke-width="1.4"/><circle cx="${x}" cy="${y}" r="2.3" fill="#7E2416"/>`).join("");
    if(o.char){for(let k=0;k<10;k++){const a=k*Math.PI/5+.3,rr=R0-1.8;s+=`<circle cx="${(cx+rr*Math.cos(a)).toFixed(1)}" cy="${(cy+rr*Math.sin(a)).toFixed(1)}" r="1.8" fill="#4A2A14"/>`;}}
    for(let k=0;k<(o.cuts||0)/2;k++){const a=k*Math.PI/((o.cuts||2)/2);s+=`<line x1="${(cx+R0*Math.cos(a)).toFixed(1)}" y1="${(cy+R0*Math.sin(a)).toFixed(1)}" x2="${(cx-R0*Math.cos(a)).toFixed(1)}" y2="${(cy-R0*Math.sin(a)).toFixed(1)}" stroke="${crustD}" stroke-width="1.2" opacity=".85"/>`;}}
  else if(o.shape==="square"||o.shape==="sheet"){const [x,y,w,h]=o.shape==="sheet"?[6,12,108,66]:[16,8,88,74],ins=4;
    s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="${crust}" stroke="${ink}" stroke-width="2"/>`;
    s+=`<rect x="${x+ins}" y="${y+ins}" width="${w-2*ins}" height="${h-2*ins}" rx="2" fill="${o.cheese?cheese:sauce}"/>`;
    if(o.sauceTop)for(let k=0;k<4;k++)s+=`<path d="M${x+ins+2} ${y+14+k*16} q${(w-2*ins)/4} -7 ${(w-2*ins)/2} 0 t${(w-2*ins)/2-4} 0" fill="none" stroke="${sauce}" stroke-width="6" stroke-linecap="round"/>`;
    if(o.dollops)s+=dots([[30,22],[54,20],[80,24],[40,42],[66,40],[88,46],[28,62],[52,64],[78,66]],5.5,sauce);
    if(o.romano)s+=dots([[18,22],[34,30],[50,20],[68,28],[86,22],[100,32],[24,48],[44,54],[62,46],[80,56],[98,50],[30,66],[56,68],[90,68]],1.6,romano);
    const cx=o.cuts||3;for(let k=1;k<cx;k++){const lx=x+k*w/cx;s+=`<line x1="${lx.toFixed(1)}" y1="${y}" x2="${lx.toFixed(1)}" y2="${y+h}" stroke="${crustD}" stroke-width="1.2" opacity=".85"/>`;}
    const cy=o.shape==="sheet"?2:3;for(let k=1;k<cy;k++){const ly=y+k*h/cy;s+=`<line x1="${x}" y1="${ly.toFixed(1)}" x2="${x+w}" y2="${ly.toFixed(1)}" stroke="${crustD}" stroke-width="1.2" opacity=".85"/>`;}}
  else if(o.shape==="roll"){[[14,20],[40,48]].forEach(([x,y])=>{s+=`<rect x="${x}" y="${y}" width="66" height="24" rx="12" fill="${crust}" stroke="${ink}" stroke-width="2"/><path d="M${x+60} ${y+12} m-6 0 a6 6 0 1 0 6 -6 a4 4 0 1 0 -4 4" fill="none" stroke="${sauce}" stroke-width="2.4"/>`;});
    s+=`<ellipse cx="96" cy="70" rx="13" ry="7" fill="${sauce}" stroke="${ink}" stroke-width="2"/>`;}
  else if(o.shape==="half"){s+=`<path d="M14 62 A46 46 0 0 1 106 62 Z" fill="${crust}" stroke="${ink}" stroke-width="2"/><path d="M21 60 A39 39 0 0 1 99 60 Z" fill="${cheese}"/>`+dots([[40,46],[60,34],[80,46],[52,54],[70,52]],5,mozz)+dots([[48,40],[72,40],[62,48]],3.5,sauce);}
  return `<svg viewBox="0 0 120 90" aria-hidden="true" focusable="false">${s}</svg>`;}
function styleCard(s,n){const spots=styleSpots(s);const sd=styleDish(s);
  return `<article class="pie" id="style-${s.id}"><div class="piehead"><span class="fnum">${n}</span><div class="piepic">${pizzaSVG(s.art)}</div></div>
    <span class="where">${esc(s.home)}</span><h3>${esc(s.n)}</h3>
    <dl>${[["Crust",s.crust],["Sauce",s.sauce],["Cheese",s.cheese]].filter(([,v])=>v).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join("")}</dl>
    <p>${esc(styleText(s))}</p><p class="pieorder"><b>Order like a local:</b> ${esc(s.order)}</p>
    ${spots.length?`<div class="piespots"><span class="eyebrow">Where locals send you</span>${spots.map(([nm,t])=>`<span class="piespot"><b>${esc(nm)}</b> <small>${esc(t)}</small>${mapsLink(gmaps(nm,t),false,true)}</span>`).join("")}</div>`
      :`<div class="piespots none"><span class="eyebrow">Spots wanted</span><span>Know the one locals swear by? <a href="#vote">Nominate it</a>.</span></div>`}
    <a class="more" href="${styleHref(s)}">${sd?`The ${esc(sd.d.n)} page →`:`More from ${esc(R(s.rid).name)} →`}</a></article>`;}
PAGES.catState=(cat,st)=>{const C=FOOD_CATS[cat],S=STATES[st];const all=stylesIn(cat,st);if(!C||!S||!all.length)return PAGES.notfound();
  const pies=all.filter(s=>s.group==="pie"),cousins=all.filter(s=>s.group==="cousin");const tr=TRAILS.find(t=>t.id===C.trail);
  const ans=`The Local Legends Map counts ${pies.length} pizza styles born in ${S.n}: ${listJoin(pies.map(s=>`${s.n.replace(/ Pizza$/,"")} (${s.home})`))}. Plus ${cousins.length} local cousins that locals won't call pizza: ${listJoin(cousins.map(s=>s.n))}. Places are voted by locals on Local Legends Map.`;
  const qa=qaBlock([["What is Buffalo-style pizza?",styleText(STYLES.find(s=>s.id==="ny-buffalo"))],
    ["What's the difference between a grandma pie and a Sicilian slice?","Both are square. A Sicilian rises in the pan, so it's thick and airy. A grandma pie is thin, pressed into an oiled pan and topped with mozzarella first, then crushed tomato."],
    ["Is Utica tomato pie pizza?","Locals will tell you no. It's a thick, focaccia-style crust baked in a sheet pan with thick tomato sauce and grated Romano, no mozzarella, eaten at room temperature or cold."],
    ["What is a bar pie?","A small, cracker-thin pie with cheese out to the edge, made to go with a beer. Staten Island taverns are known for it."],
    tr?[`Where can I try ${S.n}'s pizza styles in one trip?`,`Follow ${tr.name}: ${tr.stops.length} stops from ${tr.stops[0].t} to ${tr.stops[tr.stops.length-1].t}. ${tr.tip||""}`.trim()]:null]);
  const ld=ldTag({"@context":"https://schema.org","@type":"ItemList",name:`Pizza styles of ${S.n}`,itemListElement:all.map((s,k)=>({"@type":"ListItem",position:k+1,name:s.n,description:styleText(s)}))});
  return {path:`/${C.path}/${S.slug}/`,title:`The Pizza Styles of ${S.n} State`,html:`
  ${crumbs([["Home","#home"],[C.n,`#${cat}`],[S.n,""]])}
  <div class="pagehead"><span class="eyebrow">Food guide · ${esc(C.n)} · ${esc(S.n)}</span><h1>The Pizza Styles of ${esc(S.n)} State</h1>${answerBlock(`How many pizza styles does ${S.n} have?`,ans)}
    <p class="lede">Ask for "a slice" in Brooklyn, Buffalo and Utica and you'll get three different things. Here's what each place means by pizza, and where locals get it.</p></div>
  <div class="piejump" aria-label="Jump to a style">${all.map((s,k)=>`<a href="#pizza-${st}" data-jump="style-${s.id}"><span>${k+1}</span>${esc(s.n)}</a>`).join("")}</div>
  <section class="band piemapband"><div class="sec-head"><h2>Where each style was born</h2><a href="#t-${esc(C.trail)}">${tr?esc(tr.name):"The trail"} →</a></div><div class="mapbox" id="piemap"></div></section>
  <section class="band"><div class="sec-head"><h2>The pies</h2></div><div class="pies">${pies.map((s,k)=>styleCard(s,k+1)).join("")}</div></section>
  <section class="band"><div class="sec-head"><h2>Pizza's cousins</h2></div><p class="muted" style="margin:-6px 0 14px;max-width:60ch">Made from pizza dough, sold at pizzerias and bakeries, and locals will argue they're not pizza at all.</p><div class="pies">${cousins.map((s,k)=>styleCard(s,pies.length+k+1)).join("")}</div></section>
  <div class="crow" style="margin-top:22px"><a class="btn" href="#t-${esc(C.trail)}">Follow the Pizza Trail</a><a class="btn ghost" href="#theme-${esc(C.theme)}">All pizza crawls</a><a class="btn ghost" href="#vote">Nominate a style we missed</a></div>
  <div class="co4tail">${qa}${ld}${shareBox({title:`The Pizza Styles of ${S.n} State`,sub:`${all.length} styles`,kind:"Food guide",path:`/${C.path}/${S.slug}/`})}</div>`,
  after(){const mapwrap=nyMap({active:[...new Set(all.map(s=>s.rid))]});const g=document.createElementNS(NS,"g");mapwrap.svg.appendChild(g);
    spreadPins(all.map(s=>{const r=R(s.rid);return P(r.lat,r.lon);}),1).forEach(([x,y],i)=>pushPin(g,x,y,i+1,1));
    $("#piemap").appendChild(mapwrap);
    document.querySelectorAll("[data-jump]").forEach(a=>a.addEventListener("click",e=>{const t=document.getElementById(a.dataset.jump);if(t){e.preventDefault();t.scrollIntoView({behavior:"smooth",block:"start"});}}));}};};
PAGES.catHub=cat=>{const C=FOOD_CATS[cat];if(!C)return PAGES.notfound();const live=Object.keys(STATES).filter(st=>stylesIn(cat,st).length);
  return {path:`/${C.path}/`,title:"Pizza Styles by State",html:`
  ${crumbs([["Home","#home"],[C.n,""]])}
  <div class="pagehead"><span class="eyebrow">Food guide · ${esc(C.n)} across America</span><h1>Pizza Styles by State</h1>${answerBlock("What are the regional pizza styles in the US?",`Nearly every pizza town has its own style. New York alone has ${stylesIn(cat,"ny").filter(s=>s.group==="pie").length} on the map, from the folded New York slice to Buffalo's cup-and-char pepperoni. Detroit, Chicago, New Haven, Trenton, Old Forge and St. Louis are next. Places are voted by locals on Local Legends Map.`)}
    <p class="lede">Every pizza town thinks theirs is the real one. We map each style where it was born, then send you to the places locals swear by.</p></div>
  <section class="band"><div class="sec-head"><h2>On the map now</h2></div><div class="tgrid">${live.map(st=>{const S=STATES[st],l=stylesIn(cat,st);return `<a class="tcard" href="#${cat}-${st}"><span class="meta">${esc(S.n)} · ${l.length} styles</span><b>The Pizza Styles of ${esc(S.n)}</b><p>${esc(listJoin(l.filter(s=>s.group==="pie").map(s=>s.n)))}.</p><span class="readbtn">Read the guide</span></a>`;}).join("")}</div></section>
  <section class="band"><div class="sec-head"><h2>Next on the map</h2></div><p class="muted" style="margin:-6px 0 14px;max-width:60ch">Styles other states are known for. They get their own guide as each state goes live.</p>
    <ul class="nextstyles">${STYLES_NEXT.map(([n,w])=>`<li><b>${esc(n)}</b><span>${esc(w)}</span></li>`).join("")}</ul>
    <div class="crow" style="margin-top:16px"><a class="btn ghost" href="#vote">Nominate your town's style</a></div></section>`};};
/* pizza dish pages link back to the state guide */
{const _dP=PAGES.dish;PAGES.dish=(rid,i)=>{const p=_dP(rid,i);const s=STYLES.find(x=>{const sd=styleDish(x);return sd&&sd.r.id===rid&&sd.i===+i;});
  if(s&&p.path!=="/404/"){const S=STATES[s.st];p.html=p.html.replace(/(<\/h1>)/,`$1<a class="stylechip" href="#${s.cat}-${s.st}">One of the ${stylesIn(s.cat,s.st).length} pizza styles of ${esc(S.n)} →</a>`);}return p;};}
/* "pizza" in the search box goes to the guide instead of the first pizza dish */
function catSearch(q){const cat=Object.keys(FOOD_CATS).find(c=>q===c||q===c+"s"||q===c+" styles"||q===FOOD_CATS[c].n.toLowerCase());if(!cat)return null;return `#${cat}-ny`;}
