function route(){
  const h=routeKey(); let m, page;
  if(h==="home") page=PAGES.home();
  else if(h==="ny") page=PAGES.ny();
  else if((m=h.match(/^s-([a-z]{2})$/))) page=m[1]==="ny"?PAGES.ny():PAGES_EXTRA.soonState(m[1]);
  else if((m=h.match(/^rg-([a-z]+)$/))) page=PAGES_EXTRA.regionHub(m[1]);
  else if((m=h.match(/^r-([a-z]+)$/))) page=PAGES.region(m[1]);
  else if((m=h.match(/^d-([a-z]+)-(\d+)$/))) page=PAGES.dish(m[1],m[2]);
  else if(h==="trails"){hubFilter="All";page=PAGES.trails();}
  else if(h==="crawls"){hubFilter="fmt:Crawl";page=PAGES.trails("crawls");}
  else if(h==="trail-list"){hubFilter="fmt:Trail";page=PAGES.trails("trail-list");}
  else if(h==="roadtrips"){hubFilter="fmt:Road trip";page=PAGES.trails("roadtrips");}
  else if((m=h.match(/^theme-([a-z]+)$/))) page=PAGES_EXTRA.theme(m[1]);
  else if((m=h.match(/^t-([a-z0-9]+)$/))) page=PAGES.trail(m[1]);
  else if((m=h.match(/^rt-([a-z]+)$/))) page=PAGES.roadtrip(m[1]);
  else if(h==="f-hotdogs") page=PAGES.feature();
  else if(FOOD_CATS[h]) page=PAGES.catHub(h);
  else if((m=h.match(/^([a-z]+)-([a-z]{2})$/))&&FOOD_CATS[m[1]]) page=PAGES.catState(m[1],m[2]);
  else if(h==="guide") page=PAGES.guide();
  else if(h==="list") page=PAGES.list();
  else if(h==="news") page=PAGES_EXTRA.news();
  else if(h==="programs") page=PAGES.programs();
  else if(h==="events") page=PAGES.events();
  else if(h==="f-factories") page=PAGES.factories();
  else if(h==="vote") page=PAGES_EXTRA.vote();
  else if(h==="cravings") page=PAGES_EXTRA.cravings();
  else if(h==="missing") page=PAGES_EXTRA.missing();
  else if(h==="desk") page=PAGES_EXTRA.desk();
  else if((m=h.match(/^e-([a-z0-9-]+)$/))) page=PAGES_EXTRA.event(m[1]);
  else if((m=h.match(/^season-([a-z]+)$/))) page=PAGES_EXTRA.season(m[1]);
  else if(h==="plan") page=PAGES_EXTRA.plan();
  else if(h==="organizers") page=PAGES_EXTRA.organizers();
  else if(h==="sponsors") page=PAGES_EXTRA.sponsors();
  else page=PAGES.notfound();
  document.body.classList.toggle("is-home",h==="home");$("#app").innerHTML=page.html; $("#urlchip").textContent="locallegendsmap.com"+page.path;
  if(window.__booted||!document.querySelector('link[rel="canonical"]'))document.title=page.title==="HOME"?"The Local Legends Map":page.title+" · The Local Legends Map";window.__booted=1;
  document.querySelectorAll(".mainnav a").forEach(a=>{const k=a.dataset.sec;a.classList.toggle("on",(k==="ny"&&/^(ny|s-ny|rg-|r-|d-)/.test(h))||(k==="trails"&&/^(trails|t-|rt-|guide|programs|crawls|trail-list|roadtrips|theme-)/.test(h))||(k==="f"&&/^(f-|pizza)/.test(h))||(k==="list"&&h==="list")||(k==="news"&&h==="news")||(k==="events"&&(h==="events"||/^e-/.test(h)))||(k==="vote"&&(h==="vote"||h==="desk")));});
  page.after&&page.after(); window.scrollTo(0,0); $("#app").focus({preventScroll:true});
}
window.addEventListener("hashchange",route);
(function(){const b=document.querySelector(".menubtn"),n=document.getElementById("mainnav");if(!b||!n)return;
  b.addEventListener("click",()=>{const o=n.classList.toggle("open");b.setAttribute("aria-expanded",o);b.classList.toggle("open",o);});
  window.addEventListener("hashchange",()=>{n.classList.remove("open");b.classList.remove("open");b.setAttribute("aria-expanded","false");});})();
$("#townlist").innerHTML=townIndex.map(([t])=>`<option value="${esc(t)}">`).sort().join("");
bindSearch("#topSearch","#tq","#tmsg");
/* drop-down order: up to 2 Featured (paid, always labeled) on top, then most popular by member votes.
   Featured = a presenting sponsor (SPONSOR) or a paid promotion (PROMOTED). Money never changes the vote order below. */
const PROMOTED=[]; /* ids of trails/crawls whose builders paid to promote them */
const isFeat=t=>!!(SPONSOR[t.id]||PROMOTED.includes(t.id));
function ddOrder(list){const byVotes=(a,b)=>b.score-a.score||a.name.localeCompare(b.name);
  const seenT=new Set();const feat=list.filter(t=>isFeat(t)&&t.inSeason).sort(byVotes).filter(t=>!seenT.has(t.theme)&&seenT.add(t.theme)).slice(0,2).map(t=>({...t,feat:true}));
  const rest=list.filter(t=>!feat.some(f=>f.id===t.id)).sort((a,b)=>(b.inSeason?1:0)-(a.inSeason?1:0)||byVotes(a,b));
  const shown=[],more={};rest.forEach(t=>{const same=rest.filter(x=>x.theme===t.theme&&x.theme!=="roadfood");if(same.length>1&&same[0]!==t){more[t.theme]=(more[t.theme]||0)+1;return;}shown.push(t);});
  const out=[];shown.forEach(t=>{out.push(t);if(more[t.theme]&&rest.filter(x=>x.theme===t.theme)[0]===t)out.push({more:more[t.theme],theme:t.theme});});
  return [...feat,...(feat.length<2?[{slot:true}]:[]),...out];}
function buildDD(){const box=document.getElementById("ddpanel");if(!box)return;const all=allTrails();
  const cols=[["Crawl","Crawls","One food, one area, on foot or a short hop.","#crawls"],["Trail","Trails","A themed route across a region, usually by car.","#trail-list"],["Road trip","Road trips","Multi-day, multi-region. The long haul.","#roadtrips"]];
  box.innerHTML=cols.map(([f,label,def,href])=>{const list=all.filter(t=>t.fmt===f);
    return `<div class="ddcol dd-${f==="Road trip"?"road":f.toLowerCase()}"><a class="ddhead" href="${href}"><b>${label}</b><span class="ddcount">${list.length}</span></a><p class="dddef">${def}</p>
    <ul class="ddlist">${ddOrder(list).map(t=>t.more?`<li class="ddmore"><a href="#theme-${t.theme}">+ ${t.more} more in ${esc(THEMES[t.theme].n)} →</a></li>`:t.slot?`<li class="ddslot"><a href="#programs"><span>Featured spot open</span><small>Sponsor a ${f==="Road trip"?"road trip":f.toLowerCase()} and appear here</small></a></li>`
      :`<li class="${t.feat?"ddfeat":""} ${t.inSeason?"":"ddoff"}"><a href="${t.href}">${t.feat?`<em class="featag">Featured</em>`:""}<span>${esc(t.name)}</span>${isSeasonal(t.id)?`<small class="ddseason">${t.inSeason?"In season · "+monthsLabel(SEASON[t.id].m):"Off-season · back in "+backIn(t.id)}</small>`:""}<small>${t.feat&&SPONSOR[t.id]?"Presented by "+esc(SPONSOR[t.id].name)+" · ":""}${esc(t.meta)} · ▲ ${t.score}</small></a></li>`).join("")}</ul><a class="ddall" href="${href}">See all ${label.toLowerCase()} →</a></div>`;}).join("")+
    `<div class="ddfoot"><a href="#guide">What's the difference? Crawl vs. trail vs. road trip</a><a href="#trails">All crawls, trails and road trips →</a></div>`;
  const dd=box.parentElement;box.addEventListener("click",e=>{if(e.target.closest("a")){dd.classList.add("shut");document.activeElement&&document.activeElement.blur();}});
  if(!dd._bound){dd._bound=1;dd.addEventListener("mouseleave",()=>dd.classList.remove("shut"));}}
buildDD();
