if(CALM){document.body.classList.add("calm");const bb=document.createElement("nav");bb.className="bottombar";bb.setAttribute("aria-label","Quick links");
  bb.innerHTML=[["#ny","Explore","ny|r-|d-|cravings"],["#trails","Trails","trails|t-|rt-|crawls|trail-list|roadtrips|theme-|guide"],["#events","Events","events"],["#vote","Vote","vote"]].map(([h,l,m])=>`<a href="${h}" data-m="${m}">${l}</a>`).join("");
  document.body.appendChild(bb);const mark=()=>{const h=(location.hash||"#home").slice(1);bb.querySelectorAll("a").forEach(a=>a.classList.toggle("on",new RegExp("^("+a.dataset.m+")").test(h)));};window.addEventListener("hashchange",mark);mark();}
